  const tags = [t({ side: "starved", chancePenalty: 30 }), t({ side: "crowded", chancePenalty: 9 }), t({ side: "floored", chancePenalty: 18 }), t({ side: "empowered", chancePenalty: -8 }), t({ side: "meaningless", chancePenalty: 20 })].map(x => x.tag + " " + x.tip).join(" ");
