  const ge164 = C164.locations?.the_great_engine, ah164 = C164.locations?.archive_hollow;
  const b164 = (l) => raw164.substrateDensity[l.regionId || l.region];
  // ✅ ERIK 2026-09-11: "turn the empowering pools on."
