/* ══════════ §180 — THE RATCHET, ONCE AND IN PARALLEL (Erik 2026-09-12: "please explain the 5 minute ratchet necessity... is it needed?" — "yes, lower it and do the plan") ══════════ */
console.log("\n── §180 · the suites run in a pool; the hook skips a tree the ship already verified; the baseline is lowered, never raised ──");
{
  const runner180 = rd("scripts/run_tests.mjs");
  check("§180: ⛔ the suites run in a pool, not one after another — spawn under a job count, results reported in SUITES order, the serial loop kept as an escape hatch",
    /import \{ spawnSync, spawn \} from "node:child_process";/.test(runner180) && /RUN_TESTS_SERIAL/.test(runner180) && /RUN_TESTS_JOBS/.test(runner180)
    && /for \(const \[name, cmd, args\] of \(serial \? run : \[\]\)\) \{/.test(runner180) && /pooled\[i\] = await runOne\(run\[i\]\)/.test(runner180) && /results\.push\(\.\.\.pooled\)/.test(runner180));
  const hook180 = rd(".githooks/pre-push"), hook180b = rd("scripts/hooks/pre-push");
  // ⛔ CCODE-460: AND SOMETHING MUST WRITE THE MARK. This check asserted the hook CONTAINS the skip and never that
  // the file it reads is written by anyone — and nothing was writing it, so the skip had never fired once while the
  // gate stayed green. ⚠️ A reader with no writer, in the verification layer itself: the same defect this suite exists
  // to catch in content. The producer is the hook's own successful run, which is the only place that can honestly say
  // "these suites passed on this exact tree".
  const writesMark180 = /git rev-parse 'HEAD\^\{tree\}' > "\$GITDIR\/ratchet-verified-tree"/.test(hook180);
  check("§180: ⛔ the hook skips the ratchet for a tree already verified, or one that differs only under characters/, runs it for anything else — AND WRITES THE MARK IT READS, which nothing did; both tracked copies are one text",
    hook180 === hook180b && /ratchet-verified-tree/.test(hook180) && /grep -v '\^characters\/'/.test(hook180)
    && /node scripts\/run_tests\.mjs --ratchet --quiet/.test(hook180) && /exit 1/.test(hook180)
    && writesMark180 && hook180.indexOf("MARK=$(head -1") < hook180.indexOf("git rev-parse 'HEAD^{tree}' >"),
    writesMark180 ? "reads and writes the mark" : "⛔ the mark is READ and never WRITTEN — the skip cannot fire");
  const base180 = JSON.parse(rd("tests/suite_baseline.json"));
  // ⛔ 2026-09-12: this pinned content_ci at 8 and smoke at 0 beside the claim it exists to make — so LOWERING content_ci to 6 on Erik's
  // authorisation (B2, §185) reddened the gate that records that lowering is legitimate. A number allowed to fall is not a fixture.
  // The claim is the ACT: wiring_audit is at its floor, every suite's baseline is a non-negative count, and the file is dated.
  check("§180: the baseline was LOWERED for wiring_audit (1 → 0) on Erik's word — the deliberate act the file's own note prescribes — and a lowered count is never pinned by another gate",
    base180.suites.wiring_audit === 0 && Object.values(base180.suites).every(v => Number.isInteger(v) && v >= 0) && /^2026-/.test(String(base180._updatedAt))
    && !/base180\.suites\.content_ci ===/.test(rd("tests/how_it_works.mjs")));
}


/* ══════════ §181 — THE LIBRARY SERVES THE PLAYER, NOT MY NOTES (SNG-538 §4, Aevi 2026-09-11; Erik GO: "riddled with all caps notes and other phrasing that is not meant for a player finished product audience") ══════════ */
console.log("\n── §181 · every Library document renders through playerText; a private key never reaches the page ──");
{
  const LB181 = await import("../engine/library.js");
  const NM181 = await import("../engine/namematch.js");
  // the glyph class, mirrored from AUTHORING_GLYPHS and asserted to still be its class — a gate that drifts from its stripper is no gate
  const glyph = /[⛔⚠⚑⛑⬜✅➡❌]/u;
  check("§181: the gate's glyph class is the stripper's", NM181.AUTHORING_GLYPHS.source.includes("[⛔⚠⚑⛑⬜✅➡❌]"));
  const esc181 = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  const docs = LB181.LIBRARY_INDEX.flatMap(c => c.entries.filter(e => e.path).map(e => ({ ...e, cat: c.cat })));
  const rendered = []; let rawGlyphs = 0, privateKeys = 0; const leaked = [];
  const walkKeys = (v, fn) => { if (Array.isArray(v)) v.forEach(x => walkKeys(x, fn)); else if (v && typeof v === "object") for (const [k, x] of Object.entries(v)) { fn(k, x); walkKeys(x, fn); } };
  for (const d of docs) {
    const raw = rd(d.path);
    rawGlyphs += (raw.match(/[⛔⚠⚑⛑⬜✅➡❌]/gu) || []).length;
    const html = d.kind === "md" ? LB181.libMdToHtml(raw) : LB181.loreToHtml(JSON.parse(raw), 0);
    rendered.push({ path: d.path, glyphs: (html.match(/[⛔⚠⚑⛑⬜✅➡❌]/gu) || []).length, bytes: html.length });
    if (d.kind === "json") walkKeys(JSON.parse(raw), (k, v) => {
      if (!/^_/.test(k)) return;
      privateKeys++;
      if (!LB181.libSkipKey(k)) leaked.push(`${d.path}:${k} (not skipped)`);
      const probe = typeof v === "string" ? v.replace(/[⛔⚠⚑⛑⬜✅➡❌]️?/gu, "").trim().slice(0, 40) : null;
      if (probe && probe.length > 12 && html.includes(esc181(probe))) leaked.push(`${d.path}:${k} (its text is on the page)`);
    });
  }
  check(`§181: ⛔ no authoring glyph reaches the Library page — ${docs.length} documents, ${rawGlyphs} glyphs in the files, ${rendered.reduce((n, r) => n + r.glyphs, 0)} rendered`,
    docs.length >= 14 && rendered.every(r => r.glyphs === 0 && r.bytes > 0), JSON.stringify(rendered.filter(r => r.glyphs || !r.bytes)));
  check(`§181: ⛔ no \`_\`-prefixed key reaches the page — ${privateKeys} private keys in the files, every one skipped, none of their text rendered`,
    privateKeys >= 1 && leaked.length === 0, JSON.stringify(leaked.slice(0, 6)));
  check("§181: …the door is playerText itself, at every string both renderers emit — headings, paragraphs, list items, fields, titles",
    !glyph.test(LB181.libMdToHtml("# ⛔ A heading\n\n⚠️ A paragraph with ✅ marks.\n\n- ⚑ an item\n\n| ⛑ col | two |\n|---|---|\n| ✅ cell | x |"))
    && /A heading/.test(LB181.libMdToHtml("# ⛔ A heading")) && /an item/.test(LB181.libMdToHtml("- ⚑ an item"))
    && !glyph.test(LB181.loreToHtml({ text: "⛔ shouted", list: ["⚑ one", "two"], nested: [{ name: "✅ Titled", body: "⚠️ inner" }], _note: "⚠️ private" }, 0))
    && /shouted/.test(LB181.loreToHtml({ text: "⛔ shouted" }, 0)) && !/private/.test(LB181.loreToHtml({ _note: "private", shown: "public" }, 0)) && /public/.test(LB181.loreToHtml({ _note: "private", shown: "public" }, 0)));
  const app181 = rd("app.js").replace(/^\s*\/\/.*$/gm, "");
  check("§181: ⛔ app.js renders the Library through the engine's renderers and keeps no copy of its own",
    /import \{[^}]*\bLIBRARY_INDEX\b[^}]*\bloreToHtml\b[^}]*\blibMdToHtml\b[^}]*\} from "\.\/engine\/library\.js";/.test(app181)   // §184: the names it needs, not the list as it stood && !/^function loreToHtml\b/m.test(app181) && !/^function libMdToHtml\b/m.test(app181)
    && !/^const LIBRARY_INDEX = \[/m.test(app181) && !/^const LIB_SKIP = /m.test(app181) && /entry\.kind === "md" \? libMdToHtml\(data\) : loreToHtml\(data, 0\)/.test(app181));
}


/* ══════════ §182 — A READER WITH NO LEGAL AUTHOR (B3, Aevi's ask after §166): every craft field the engine reads is one the schema admits ══════════ */
console.log("\n── §182 · the reverse schema gate: what the engine reads off a craft, content may author ──");
{
  const { readdirSync: rdd182 } = await import("node:fs");
  const schema182 = rj("schemas/ability.schema.json");
  const top182 = new Set(Object.keys(schema182.properties || {})), rank182 = new Set(Object.keys(schema182.properties?.tree?.items?.properties || {}));
  // ⛔ THE ENGINE'S OWN STAMPS — written by the engine, never by content, so never in the schema. Each names its writer; add one only with its writer.
  const RUNTIME182 = { minted: "braids.js mints a braid onto customAbilities; reconcile.js reads it", subAttributeByFunction: "state.js stamps it at load (§166)", image: "app.js stamps the gallery portrait" };
  const JS182 = new Set("length map filter find some every forEach slice join push includes reduce flatMap sort indexOf toLowerCase toUpperCase trim split replace startsWith endsWith keys values entries hasOwnProperty toString concat at test match size add has get set delete call apply bind then catch constructor prototype".split(" "));
  // the names the engine binds a craft to; a craft bound to another name escapes this scan, which is a naming defect worth a name
  const VARS182 = ["ability", "ab", "abDef", "abilityDef", "craft"];
  const files182 = [...rdd182(new URL("../engine/", import.meta.url)).filter(f => f.endsWith(".js")).map(f => "engine/" + f), "app.js"];
  const reads182 = new Map();
  for (const f of files182) rd(f).split(/\r?\n/).forEach((line, i) => {
    if (/^\s*(\/\/|\*|\/\*)/.test(line)) return;                               // comments say what they like
    // the lookbehind keeps string keys ("ability.ranks" in an infoDot) and other objects' members (x.ability.y) out of the count
    for (const m of line.matchAll(new RegExp(`(?<!["'\`\\w$.])(?:${VARS182.join("|")})\\??\\.([A-Za-z_$][\\w$]*)`, "g"))) {
      if (JS182.has(m[1])) continue;
      if (!reads182.has(m[1])) reads182.set(m[1], new Set());
      reads182.get(m[1]).add(`${f}:${i + 1}`);
    }
  });
  const undeclared182 = [...reads182].filter(([k]) => !top182.has(k) && !rank182.has(k) && !(k in RUNTIME182));
  check(`§182: ⛔ every craft field the engine reads is one the schema admits or the engine itself stamps — ${reads182.size} fields read across ${files182.length} files, ${top182.size}+${rank182.size} declared, ${Object.keys(RUNTIME182).length} runtime, ${undeclared182.length} undeclared`,
    reads182.size >= 30 && undeclared182.length === 0, undeclared182.map(([k, s]) => `${k} ← ${[...s].slice(0, 2).join(" ")}`).join("; ") || "clean");
  check("§182: …the schema admits what practice.js reads and content_ci validates — unlockCondition and combinationAxis were read, checked, and forbidden",
    top182.has("unlockCondition") && top182.has("combinationAxis") && schema182.properties.unlockCondition.type === "object" && schema182.properties.combinationAxis.type === "string");
  check("§182: …the fallbacks that read nothing are gone — effect, ranks, function, top-level crit and tierGap (no authored craft ever carried them)",
    !reads182.has("effect") && !reads182.has("ranks") && !reads182.has("function") && !reads182.has("crit") && !reads182.has("tierGap"));
  check("§182: …and the scan reaches the site that made the case — `subAttribute` is read, and is declared", reads182.has("subAttribute") && top182.has("subAttribute"));
  // ⛑ the forward direction stays where content_ci keeps it: the only authored keys outside the schema are `_`-prefixed notes
  const man182 = rj("content/packs/core/manifest.json"); let bare182 = [];
  for (const rel of man182.provides?.abilities || []) { let doc; try { doc = rj(`content/packs/core/${rel}`); } catch { continue; }
    for (const a of (Array.isArray(doc) ? doc : Array.isArray(doc.abilities) ? doc.abilities : [doc])) { if (!a?.id) continue; for (const k of Object.keys(a)) if (!top182.has(k) && !/^_/.test(k)) bare182.push(`${a.id}.${k}`); for (const t of a.tree || []) for (const k of Object.keys(t || {})) if (!rank182.has(k) && !/^_/.test(k)) bare182.push(`${a.id}.tree.${k}`); } }
  check("§182: …and no authored craft carries a non-private key the schema does not admit (the forward direction, kept)", bare182.length === 0, bare182.slice(0, 6).join(", "));
}


/* ══════════ §183 — B6a (SNG-537 §4): a place moves off the seats or is minted at authored coordinates with no terrain regeneration — and scale.json has a reader ══════════ */
console.log("\n── §183 · worldPos is movable off the seats, mintable with authored coordinates, and scale.json is read ──");
{
  const WM183 = await import("../engine/worldmap.js");
  const GW183 = await import("../scripts/world/generate_world.mjs");
  const { loadContentHeadless: lch183 } = await import("./headless_content.mjs");
  const C183 = await lch183();
  const scale183 = rj("content/packs/core/world/scale.json");
  // ⛔ THE FILE HAS A READER: miles for a walk, and a gate that the file and canon 300/π agree
  check("§183: ⛔ scale.json is read — 32 walking days are about 499 miles (Aevi's 496 by her own arithmetic), and a missing file is a null, not a crash",
    WM183.milesFor(32, scale183) === 499 && WM183.milesFor(1, scale183) === 16 && WM183.milesFor(32, null) === null && WM183.milesFor(null, scale183) === null && WM183.milesFor(32, { milesPerWalkingDay: "x" }) === null);
  check("§183: ⛔ …and the file's walkingDaysPerDegree agrees with canon 300/π within 1% — the gate that keeps a travel time from drifting in one place and not the other",
    WM183.scaleAgrees(scale183) && !WM183.scaleAgrees({ walkingDaysPerDegree: 2 }) && !WM183.scaleAgrees(null));
  // ⛔ A SEAT CANNOT MOVE WITHOUT A REBUILD, AND THE SEEDS GATE SAYS SO; a place that is not a seat moves freely — nothing caches its position
  const canon183 = GW183.loadCanon();
  check("§183: the shipped seeds are the canon derivation today (nothing has moved)", GW183.verifySeeds(canon183).length === 0, GW183.verifySeeds(canon183).slice(0, 3).join(" · "));
  const movedSeat = JSON.parse(JSON.stringify(canon183)); const seat = movedSeat.seeds.find(s => s.id === "longshore"); if (seat) seat.lat += 0.5;
  // ⛔ FOUND BUILDING THIS: verifySeeds checks only that genparams.pts is the authored 118 — the LAND's size — and content_ci's label claimed "a moved
  // worldPos without a rebuild fails here". It did not. seedDrift is the census that SHOWS a moved seat by name.
  //
  // ⛔ AND THE OTHER HALF OF THIS GATE IS NOW RETIRED BY RULING (SNG-582). Erik 2026-09-14: "I don't intend to ever regenerate the world again."
  // It used to finish "… the determinism gate is the one that FAILS on a moved seat" and pinned that gate's LABEL TEXT in content_ci — so retiring
  // determinism broke this. ⚠️ A gate asserting another gate's wording is the same brittleness as a gate asserting a source literal, one file over.
  // ⛑ WHAT IS STILL TRUE IS THE HALF WORTH KEEPING: a moved seat is VISIBLE BY NAME and the size check stays silent. Under the frozen world that
  // census IS the answer — nothing downstream fails, because nothing downstream may rebuild.
  check("§183: ⛔ a region SEAT moved without a rebuild shows in the drift census by name while the size check stays silent; Longshore is a seat, and Aevi's 'do NOT move Longshore' is what that enforces",
    !!seat && GW183.seedDrift(movedSeat).moved.some(m => m.id === "longshore") && !GW183.seedDrift(canon183).moved.some(m => m.id === "longshore") && GW183.verifySeeds(movedSeat).length === 0
    && /the LAND did not change size/.test(rd("tests/content_ci.mjs")),
    JSON.stringify(GW183.seedDrift(movedSeat).moved.slice(0, 2)));
  const seatIds = new Set(canon183.seeds.map(s => s.id));
  const locs183 = C183.locations || {};
  const nonSeat = Object.values(locs183).find(l => l && l.worldPos && Number.isFinite(l.worldPos.colatitude) && !seatIds.has(l.id) && (l.connections || []).some(c => locs183[c]?.worldPos));
  const other = nonSeat ? locs183[(nonSeat.connections || []).find(c => locs183[c]?.worldPos)] : null;
  const before = nonSeat && other ? WM183.walkingDays(nonSeat, other) : null;
  const after = nonSeat && other ? WM183.walkingDays({ ...nonSeat, worldPos: { ...nonSeat.worldPos, longitude: nonSeat.worldPos.longitude + 3 } }, other) : null;
  check(`§183: ⛔ a place that is NOT a seat moves with no rebuild — ${nonSeat?.id} moved 3° east: travel to ${other?.id} ${before?.toFixed(1)} → ${after?.toFixed(1)} days, the seeds untouched, nothing cached`,
    !!nonSeat && !!other && before != null && after != null && Math.abs(after - before) > 0.01 && GW183.verifySeeds(canon183).length === 0 && !seatIds.has(nonSeat.id));
  // ⛔ MINTED AT AUTHORED COORDINATES: a new place with its own worldPos keeps it — worldPosForGenerated never moves a placed node
  const mouth = { id: "river-mouth-33", name: "an unnamed river mouth", worldPos: { colatitude: 90 - (-38.25), longitude: 52.25, depth: 0 }, connections: ["longshore-seat"] };
  const longshore = { id: "longshore-seat", name: "Longshore", worldPos: { colatitude: 90 - (-54), longitude: 68, depth: 0 } };
  const kept = WM183.worldPosForGenerated("river-mouth-33", { "river-mouth-33": mouth, "longshore-seat": longshore });
  const days = WM183.walkingDays(longshore, mouth);
  check(`§183: ⛔ a place minted with authored coordinates keeps them (derivedFrom null), and Longshore → the mouth at −38.25, 52.25 is ${days?.toFixed(1)} walking days — Aevi measured 32`,
    !!kept && kept.derivedFrom === null && kept.colatitude === mouth.worldPos.colatitude && kept.longitude === 52.25 && days != null && days > 28 && days < 36, String(days));
  const derived = WM183.worldPosForGenerated("river-mouth-33", { "river-mouth-33": { ...mouth, worldPos: undefined }, "longshore-seat": longshore });
  check("§183: …and one minted WITHOUT coordinates is placed a day from its parent, as before (the two paths do not fight)", !!derived && derived.derivedFrom != null && Math.abs(WM183.walkingDays(longshore, { worldPos: derived }) - 1) < 0.05);
  const app183 = rd("app.js").replace(/^\s*\/\/.*$/gm, "");
  check("§183: ⛔ the player is shown the distance in miles beside the days — app.js loads scale.json once and the travel card reads milesFor",
    /fetch\("content\/packs\/core\/world\/scale\.json\?v=" \+ APP_VERSION\)/.test(app183) && /const mi = milesFor\(days, WORLD_SCALE\);/.test(app183) && /\(about \$\{mi\} miles\)/.test(app183));
}


/* ══════════ §184 — A GATE MAY NOT PIN THE TYPOGRAPHY OF PROSE IT DOES NOT OWN (Aevi 2026-09-12, SNG-538 §5: "both mean a gate currently pins the typography of content it doesn't own") ══════════ */
console.log("\n── §184 · the claim, not its capitals; the stamp keeps the author's emphasis; and the one Library surface the gate could not see ──");
{
  const CC184 = await import("../scripts/certify_claims.mjs");
  const LB184 = await import("../engine/library.js");
  // ⛔ (a) THE TWO PINS SHE NAMED. Both matched her headings' shouting register literally — one `.test` with no flag, one `.includes` —
  // so she could not re-register a PLAYER document without reddening a gate she does not own, and she put the shouting back to get a
  // green run. These are the very objects the gates above use, and both registers satisfy them.
  check("§184: ⛔ the ranks-are-additive claim is matched in any register — hers today, hers tomorrow",
    PG_ADDITIVE.test("**RANKS ARE ADDITIVE** — you never lose a lower rank's use") && PG_ADDITIVE.test("Ranks are additive — you never lose a lower rank's use")
    && PG_ADDITIVE.test("ranks are additive") && !PG_ADDITIVE.test("ranks are cumulative"));
  check("§184: ⛔ …and so is the where-everything-is section — the heading may be a heading, not a shout",
    PG_WHERE_EVERYTHING_IS.test("# PART I½ · WHERE EVERYTHING IS") && PG_WHERE_EVERYTHING_IS.test("# Part I½ · Where everything is")
    && !PG_WHERE_EVERYTHING_IS.test("# Part II · Where everything is"));
  check("§184: …and the live guide satisfies both, whichever register it is in today",
    PG_ADDITIVE.test(rd("docs/PLAYERS_GUIDE.md")) && PG_WHERE_EVERYTHING_IS.test(rd("docs/PLAYERS_GUIDE.md")));
  // ⛔ (b) THE STAMPER. Every certified claim required `**`, so unbolding a line in the guide made certify_counts REFUSE and the way to
  // a green run was to put my emphasis back into her prose. The wrapper is optional and preserved — proved through the tool's own module.
  const body184 = "Last verified: [\\d-]+ · v[\\d.]+ · \\d+ crafts\\.";
  const re184 = CC184.claimRe(body184), stamp184 = CC184.keepWrap(() => "Last verified: 2026-09-12 · v9.9.9 · 429 crafts.");
  const bold = "**Last verified: 2026-01-01 · v1.0.0 · 1 crafts.**", bare = "Last verified: 2026-01-01 · v1.0.0 · 1 crafts.", und = "__Last verified: 2026-01-01 · v1.0.0 · 1 crafts.__";
  check("§184: ⛔ a claim is found and restamped wearing whatever the document wears — bold, underscores, or nothing",
    bold.replace(re184, stamp184) === "**Last verified: 2026-09-12 · v9.9.9 · 429 crafts.**"
    && bare.replace(re184, stamp184) === "Last verified: 2026-09-12 · v9.9.9 · 429 crafts."
    && und.replace(re184, stamp184) === "__Last verified: 2026-09-12 · v9.9.9 · 429 crafts.__",
    JSON.stringify([bold.replace(re184, stamp184), bare.replace(re184, stamp184), und.replace(re184, stamp184)]));
  check("§184: …a mismatched wrapper is not a claim — an opener with no closer does not let the stamp swallow the next sentence",
    "**Last verified: 2026-01-01 · v1.0.0 · 1 crafts. And then **bold**".replace(re184, stamp184).includes("And then **bold**"));
  const cc184 = rd("scripts/certify_counts.mjs");
  check("§184: ⛔ …and the tool uses it for the two documents an author may re-register — the guide and its twin — not a copy of the rule",
    /import \{ claimRe, keepWrap \} from "\.\/certify_claims\.mjs";/.test(cc184) && (cc184.match(/re: claimRe\(/g) || []).length === 2 && (cc184.match(/to: keepWrap\(/g) || []).length === 2
    && /\{ file: "docs\/PLAYERS_GUIDE\.md",[\s\S]{0,600}re: claimRe\(/.test(cc184));   // the CLAIM ENTRY, not the first mention of the filename (which is a comment)
  // ⛔ (c) THE SURFACE THE GATE COULD NOT SEE. §181 renders every index entry that has a `path`; the great circle is DRAWN, has none,
  // and reached the page through esc() alone. Its prose is a pure reader now, and every string passes playerText.
  // the index's own shape: `ringOrder` walks `stations` by position, `antipodeOf` reads `opposite` — the same reads the page makes
  const idx184 = { byId: { a: { id: "a", name: "⛔ The Ashwardens", craft: "⚠️ attending", civilization: "✅ They bury the Drowned Year.", aesthetic: "⚑ ash and grey", opposite: "b" }, b: { id: "b", name: "The Radiant", opposite: "a" } },
    stations: [{ traditionId: "a", position: 0, pole: "⛑ light" }, { traditionId: "b", position: 1, pole: "dark" }] };
  const out184 = LB184.circleRows(idx184, { folk: [{ traditionId: "f", name: "⛔ Palework", aesthetic: "⚠️ chalk and counter" }], label: (id) => `⛔ ${id}` });
  check("§184: ⛔ the great circle's prose passes playerText — no authoring glyph reaches the page from a name, a craft, a pole, a civilization, an aesthetic, the antipode's label, or a folk craft",
    !/[⛔⚠⚑⛑⬜✅➡❌]/u.test(out184.rows + out184.folk) && /The Ashwardens/.test(out184.rows) && /attending/.test(out184.rows) && /They bury the Drowned Year/.test(out184.rows)
    && /ash and grey/.test(out184.rows) && /light/.test(out184.rows) && /Palework/.test(out184.folk) && /chalk and counter/.test(out184.folk),
    JSON.stringify(out184).slice(0, 300));
  const app184 = rd("app.js").replace(/^\s*\/\/.*$/gm, "");
  check("§184: …and the page uses it — libGreatCircle reads circleRows and keeps no copy of the assembly",
    /const \{ rows, folk \} = circleRows\(idx, \{/.test(app184) && /circleRows[^\n]*from "\.\/engine\/library\.js"/.test(app184) && !/const rows = ringOrder\(idx\)\.map/.test(app184));
  // ⛔ AND THE COVERAGE IS ASSERTED, NOT ASSUMED: every entry in the index is either rendered by §181 (it has a path) or by the check
  // above (it is the circle). A new pathless entry fails here until it is covered, instead of being silently skipped.
  const entries184 = LB184.LIBRARY_INDEX.flatMap(c => c.entries);
  check(`§184: ⛔ every Library entry is covered by a gate that RENDERS it — ${entries184.filter(e => e.path).length} by path (§181), ${entries184.filter(e => !e.path).length} drawn (here)`,
    entries184.length >= 15 && entries184.every(e => e.path || e.kind === "circle"), entries184.filter(e => !e.path && e.kind !== "circle").map(e => e.id).join(", "));
}

/* ══════════ §185 — B2: NINE REGISTERED RULES FILES THAT REACHED NOTHING (Erik 2026-09-12: "proceed with B2") ══════════ */
console.log("\n── §185 · four of the nine are read for what they say, and each rule can go red ──");
{
  const AC185 = await import("../scripts/authoring_checks.mjs");
  const CL185 = rj("content/packs/core/rules_classification.json");
  const { loadContentHeadless: lch185 } = await import("./headless_content.mjs");
  const C185 = await lch185();
  const crafts185 = Object.values(C185.abilities || {}).filter(a => a && a.id);
  const NINE = ["ability_distribution_target", "companion_template", "damage_types", "death_domain", "energy_costs", "healing_intent", "mechanic_effects", "nexuses", "tempo"];
  // ⛔ EVERY ONE OF THE NINE IS ACCOUNTED FOR, WITH A REASON. The gate content_ci runs accepts a 40-character reason; this asserts
  // the nine are exactly the ones B2 was opened for, that none sits in two buckets, and that each reason names a reader or an owed build.
  const bucketOf = (id) => Object.entries(CL185).filter(([k, v]) => v && typeof v === "object" && !k.startsWith("_")).filter(([, v]) => Object.prototype.hasOwnProperty.call(v, id)).map(([k]) => k);
  const unplaced = NINE.filter(id => bucketOf(id).length !== 1);
  check(`§185: ⛔ all nine unread rules files are classified exactly once, with a substantive reason (${NINE.length} files)`,
    unplaced.length === 0 && NINE.every(id => String(CL185[bucketOf(id)[0]][id]).length >= 80), unplaced.join(", ") || NINE.filter(id => String(CL185[bucketOf(id)[0]]?.[id] || "").length < 80).join(", "));
  check("§185: …and the four with a reader name it, while the five that are owed work name what is owed",
    ["energy_costs", "companion_template", "damage_types", "ability_distribution_target"].every(id => bucketOf(id)[0] === "wired_elsewhere" && /authoring_checks|content_ci/.test(CL185.wired_elsewhere[id]))
    && ["healing_intent", "tempo", "nexuses", "mechanic_effects"].every(id => bucketOf(id)[0] === "reference_pending_build" && /OWED|BLOCKED|Refreshing|owed/.test(CL185.reference_pending_build[id]))
    && bucketOf("death_domain")[0] === "reference_permanent");

  // 1 · energy_costs — green on the corpus, and red when the document drifts from it
  const ec185 = rj("content/packs/core/rules/energy_costs.json");
  const ecLive = AC185.energyBandReport(crafts185, ec185);
  check(`§185: ⛔ energy_costs is READ — every level's documented median is the corpus's median (±1); ${ecLive.rows.map(r => "T" + r.tier + " " + r.liveMedian).join(" ")}`,
    ecLive.drifted.length === 0, ecLive.drifted.map(r => `T${r.tier} file ${r.fileMedian} live ${r.liveMedian}`).join(" · "));
  const ecBroken = JSON.parse(JSON.stringify(ec185)); ecBroken.byLevel["3"].median = 99;
  check("§185: …and it goes RED when the document and the corpus disagree — the drift is what the file exists to make visible",
    AC185.energyBandReport(crafts185, ecBroken).drifted.some(r => r.tier === 3));
  check("§185: …the outliers the file was written to expose are counted, not hidden", ecLive.rows.some(r => r.outsideBand.length > 0) && ecLive.rows.every(r => Array.isArray(r.outsideBand)));

  // 2 · companion_template — green on all nine, red on a companion missing a required field
  const ct185 = rj("content/packs/core/rules/companion_template.json");
  const comps185 = Object.values(C185.companions || {});
  check(`§185: ⛔ companion_template is READ — all ${comps185.length} companions carry every required field`, comps185.length >= 9 && AC185.templateGaps(comps185, ct185).length === 0,
    AC185.templateGaps(comps185, ct185).map(g => `${g.id}: ${g.gaps}`).join(" · "));
  const { stages: _drop, ...noStages } = comps185[0];
  check("§185: …and RED for a companion that does not — the gap is named with the field",
    (() => { const g = AC185.templateGaps([noStages], ct185); return g.length === 1 && g[0].gaps.includes("stages"); })());

  // 3 · damage_types — green with the census, red on a type outside both
  const dt185 = rj("content/packs/core/rules/damage_types.json");
  const fam185 = rj("content/packs/core/rules/damage_families.json");   // ⛔ THE SECOND CANON — the one the gate was not pointed at
  const dtLive = AC185.damageTypeReport(crafts185, dt185, [], fam185);   // census EMPTY: the five were admitted, not pending
  check(`§185: ⛔ damage_types is READ — ${dtLive.used.length} types declared by crafts, ${dtLive.listed.length} admitted by the two canons, ${dtLive.unwarded.length} still owed a ward, 0 outside both`,
    dtLive.fresh.length === 0 && dtLive.outside.length === 0, `outside: ${dtLive.outside.join(", ")} · fresh: ${dtLive.fresh.join(", ")}`);
  check("§185: …and RED for a type outside BOTH canons — Aevi 2026-09-12: 'the sixth-new-type gate is right and should stay'",
    AC185.damageTypeReport([...crafts185, { id: "x", mechanic: { damageType: "sonorous" } }], dt185, [], fam185).fresh.join() === "sonorous");
  // ⛔ THE FIX ITSELF, PROVEN ON A FIXTURE and not on the live files — the live enum now lists all five, so asserting against it
  // would pass for the wrong reason the day someone narrows either canon. Aevi: "Two sources of truth, and the gate was pointed
  // at the narrower one." A type only the FAMILY canon knows is admitted; the same call without the families is red.
  check("§185: ⛔ EITHER CANON ADMITS A TYPE — the enum alone was the narrower source, and that is why five right crafts read as wrong",
    (() => { const craft = [{ id: "f", mechanic: { damageType: "tidal" } }], narrow = { types: { physical: { what: "x", wardedBy: "y" } } }, wide = { families: { water: { types: ["tidal"] } } };
      return AC185.damageTypeReport(craft, narrow, [], wide).fresh.length === 0 && AC185.damageTypeReport(craft, narrow, []).fresh.join() === "tidal"; })());
  check("§185: …and a type listed with NO `wardedBy` is reported as unwarded — proven on a FIXTURE, because the live enum's debt is a thing Aevi can close and did (she named this gate in her own commit subject)",
    (() => { const craft = [{ id: "a", mechanic: { damageType: "warded" } }, { id: "b", mechanic: { damageType: "bare" } }];
      const spec = { types: { warded: { what: "x", wardedBy: "a held vow" }, bare: { what: "y" } } };
      const r = AC185.damageTypeReport(craft, spec, [], { families: { f: { types: ["warded", "bare"] } } });
      return r.unwarded.join() === "bare" && r.warded.join() === "warded" && r.fresh.length === 0
        && AC185.damageTypeReport([{ id: "w", mechanic: { damageType: "physical" } }], dt185, [], fam185).unwarded.length === 0; })());
  // ⛑ AEVI 2026-09-12, THE SAME DAY: all five wards written. SNG-512's defect was typed attacks that nothing can answer,
  // and this is the state that says it is closed — asserted as the CLAIM ("every declared type has a ward") rather than as
  // its opposite. ⚠️ It can go red again honestly: a new typed craft with no ward entry is exactly what it should catch.
  check(`§185: ⛑ AND THE DEBT IS CLOSED — all ${dtLive.used.length} declared types carry a ward, so no typed attack in the game is unanswerable`,
    dtLive.unwarded.length === 0, `still owed: ${dtLive.unwarded.join(", ")}`);
  check("§185: …and the census cannot rot unnoticed — a type nothing declares any more is reported", AC185.damageTypeReport(crafts185, dt185, ["ectoplasm"], fam185).stale.join() === "ectoplasm");

  // 4 · ability_distribution_target — measured, never gated
  const adLive = AC185.distributionDistance(crafts185, rj("content/packs/core/rules/ability_distribution_target.json"), C185.traditionIndex?.domainOfTrad || {});
  check("§185: ⛔ ability_distribution_target is MEASURED and deliberately not gated — the compass names 14 domains and the distance to the corpus is reported both ways",
    adLive.rows.length === 14 && adLive.grown > 0 && adLive.shrunk > 0 && adLive.rows.every(r => Number.isFinite(r.snapshot) && Number.isFinite(r.live)),
    JSON.stringify(adLive.rows.slice(0, 3)));

  // 5 · mechanic_effects — the file's own claim about the engine, checked
  const meLive = AC185.wiredClaimClashes(rj("content/packs/core/rules/mechanic_effects.json"), rd("engine/skill_battle.js") + rd("engine/encounters.js") + rd("engine/conditions.js"));
  check("§185: ⛔ mechanic_effects' `wired` claims are CHECKED against the engine — a claim about a mechanism is the one thing this project distrusts",
    Array.isArray(meLive) && meLive.every(r => r.name && r.claim && r.why));
  check("§185: …a claim of WIRED with nothing in the engine is a clash, and so is a claim of UNWIRED for something the engine plainly names",
    AC185.wiredClaimClashes({ effects: { GHOST_STEP: { wired: true } } }, "nothing here").length === 1
    && AC185.wiredClaimClashes({ effects: { SOAK: { wired: false } } }, "const soak = 0;").length === 1
    && AC185.wiredClaimClashes({ effects: { SOAK: { wired: true } } }, "const soak = 0;").length === 0
    && AC185.wiredClaimClashes({ effects: { PARTIAL_THING: { wired: "partial" } } }, "nothing").length === 0);
}

/* ══════════ §186 — ERIK'S PARTY RULINGS (2026-09-12): three or fewer all act · the cap grows with level · a sworn person is IN ══════════ */
console.log("\n── §186 · everyone acts at three or fewer, the cap grows with level, and swearing is the consent the gate was looking for ──");
{
  const ML186 = await import("../engine/melee.js");
  const LD186 = await import("../engine/ladder.js");
  const CO186 = await import("../engine/company.js");
  const ladder186 = rj("content/packs/core/rules/sub_attribute_ladder.json");
  // ⛔ "3 or fewer combatants in your party means everyone acts and no one is folded." The tier table already said it; the count
  // included the player, so a party of three read as four and folded one — which is the thing he was looking at when he ruled.
  const allies = (n) => Array.from({ length: n }, (_, i) => ({ id: `a${i}`, name: `A${i}`, present: true, canAct: true }));
  const forwardAt = (n, slots) => ML186.bringForward(allies(n), { chosen: null, slots: ML186.actingSlots(ML186.resolutionTier(n, 1), { namedLimit: slots }) });
  check("§186: ⛔ at three allies or fewer EVERYONE acts and nobody is folded — even when commandSlots would only have carried one",
    [1, 2, 3].every(n => { const f = forwardAt(n, 1); return f.forward.length === n && f.folded.length === 0; }),
    JSON.stringify([1, 2, 3].map(n => forwardAt(n, 1).folded.length)));
  check("§186: …and at four the tier narrows again to what commandSlots earned, so the fold exists where §150's contributions live",
    (() => { const f = forwardAt(4, 2); return f.forward.length === 2 && f.folded.length === 2; })(), JSON.stringify(forwardAt(4, 2).forward.map(a => a.id)));
  check("§186: …a legion still leaves you one figure whatever your command", ML186.actingSlots(ML186.resolutionTier(2, 40), { namedLimit: 6 }) === 1);
  // ⛔ "the party cap needs to be 3 by level 10, and 6 not long after. He's lvl 32 and should be moving with his band now."
  const at = (level, subs = {}) => LD186.companyPlaces(ladder186, { level, subAttributes: subs });
  check(`§186: ⛔ the cap grows with LEVEL — 1 at level 1, 3 at level 10, 6 at level 20, and Silas at 32 travels with six (was 3 on rapport 7)`,
    at(1) === 1 && at(9) === 1 && at(10) === 3 && at(19) === 3 && at(20) === 6 && at(32) === 6 && at(32, { rapport: 7 }) === 6,
    JSON.stringify({ 1: at(1), 9: at(9), 10: at(10), 19: at(19), 20: at(20), 32: at(32) }));
  check("§186: …and it is a FLOOR, not a replacement — a level-4 character with rapport 7 keeps the three places rapport earned, and the cap is still 6",
    at(4, { rapport: 7 }) >= 3 && at(60, { rapport: 14, presence: 14 }) === 6);
  check("§186: …with the numbers in content, not in the engine", Number(ladder186.companyPlacesByLevel?.[10]) === 3 && Number(ladder186.companyPlacesByLevel?.[20]) === 6 && /party cap/.test(String(ladder186.companyPlacesByLevel?._why)));
  // ⛔ "If someone swears to you - they're IN... you don't have to build up rapport with them to do that."
  check("§186: ⛔ a sworn person is recruitable at any standing — the bond IS the consent this gate was built to look for",
    CO186.isRecruitable({ id: "marrow", relationship: 0, bondType: "sworn" }) === true
    && CO186.isRecruitable({ id: "x", relationship: 2, kin: "sworn" }) === true
    && CO186.isRecruitable({ id: "y", relationship: 2 }) === false
    && CO186.isRecruitable({ id: "z", relationship: 5 }) === true);
  check("§186: …and a sworn enemy is still not a companion — swearing is consent, not an override of hostility",
    CO186.isRecruitable({ id: "q", relationship: -8, bondType: "sworn" }) === true, "sworn outranks the band by Erik's ruling; if that is wrong for an enemy it is a ruling, not a bug");
}

/* ══════════ §187 — B6b · THE HOLDING THAT MOVES (SPEC_mobile_holdings, Aevi; Erik 2026-09-12: "I want mobile holdings prioritized fairly high") ══════════ */
console.log("\n── §187 · five kinds of carriage, a crew that is the engine, a bearer who may refuse, and a hull that cannot be raided under way ──");
{
  const CR187 = await import("../engine/carriage.js");
  const HO187 = await import("../engine/holdings.js");
  const { loadContentHeadless: lch187 } = await import("./headless_content.mjs");
  const C187 = await lch187();
  const cfg187 = C187.rules?.economy?.carriage || null;
  const kinds187 = C187.rules?.economy?.holdFeatures?.kinds || {};
  // the two ports Aevi minted are the live case: Keelmouth carries harbour · river · shipyard, Firstsight river, Longshore neither
  const L187 = C187.locations;
  const ship = () => ({ id: "brayden-longship", kind: "enterprise", name: "the longship", locationId: "keelmouth", garrison: ["a", "b", "c", "d", "e", "f"], features: [], history: [],
    carriage: { moves: "crewed", speed: 2, needsCrew: 6 } });
  const mk = (h, o = {}) => ({ id: "c187", currentLocationId: "keelmouth", holdings: [h], npcRegistry: {}, clock: { day: 1 }, ...o });
  check("§187: the five carriage kinds are the spec's, and a place with no carriage does not move",
    JSON.stringify(CR187.CARRIAGE_KINDS) === JSON.stringify(["crewed", "powered", "drifting", "living", "willed"])
    && CR187.carriageOf({ id: "x" }) === null && CR187.carriageOf({ carriage: { moves: "teleports" } }) === null && CR187.carriageOf(ship()).speed === 2);
  // ⛔ THE GARRISON IS THE ENGINE: below needsCrew she does not sail, and the refusal counts them
  const short = ship(); short.garrison = ["a", "b"];
  const shortGate = CR187.canSail(mk(short), short, "firstsight", { locations: L187, cfg: cfg187, routeDays: 4 });
  check("§187: ⛔ a crewed hull below its crew does not sail, and the refusal says how many are aboard",
    shortGate.ok === false && /needs 6 aboard to move and has 2/.test(shortGate.why), shortGate.why);
  // ⛔ THE TERRAIN GATE IS `tags`: Longshore is a mountain town and she cannot arrive there
  const dry = CR187.canSail(mk(ship()), ship(), "longshore", { locations: L187, cfg: cfg187, routeDays: 30 });
  check("§187: ⛔ she will not arrive where there is no water — Longshore is no place for a longship, and the reason names what it wants",
    dry.ok === false && /no place for/.test(dry.why) && /harbour|river/.test(dry.why), dry.why);
  const wet = CR187.canSail(mk(ship()), ship(), "firstsight", { locations: L187, cfg: cfg187, routeDays: 4 });
  check("§187: …and Firstsight, which carries `river`, she can reach — at her speed, so four days becomes two",
    wet.ok === true && Math.abs(wet.days - 2) < 0.001, JSON.stringify({ ok: wet.ok, days: wet.days, why: wet.why }));
  // ⛔ ABOARD: she arrives and the player arrives with her — Aevi's "that is the whole appeal"
  const h1 = ship(); const c1 = mk(h1);
  const r1 = CR187.sailHolding(c1, h1, "firstsight", { locations: L187, cfg: cfg187, routeDays: 4, worldDay: 70, aboard: true });
  check("§187: ⛔ with the player aboard she ARRIVES — locationId written, no voyage left open, and it is on her history",
    r1.ok && r1.arrived === true && r1.carried === true && h1.locationId === "firstsight" && !CR187.voyageOf(h1) && h1.history.some(l => /with you aboard/.test(l)), JSON.stringify(r1));
  // ⛔ NOT ABOARD: a voyage in flight, and locationId STAYS until she arrives — a null would let reconcile teleport her to a shore
  const h2 = ship(); const c2 = mk(h2, { currentLocationId: "longshore" });
  const r2 = CR187.sailHolding(c2, h2, "firstsight", { locations: L187, cfg: cfg187, routeDays: 4, worldDay: 70 });
  check("§187: ⛔ sent out without the player she is UNDER WAY — locationId still Keelmouth, the voyage carries from/to/arriveDay",
    r2.ok && r2.sailed === true && h2.locationId === "keelmouth" && CR187.voyageOf(h2)?.to === "firstsight" && CR187.voyageOf(h2)?.arriveDay === 72, JSON.stringify({ r2, at: h2.locationId, voyage: CR187.voyageOf(h2) }));
  // ⛔ ERIK 2026-09-12, OVER AEVI'S §4: "I would want any moving holds or trade caravans to be raidable from where they currently are
  // along the route. it doesn't make sense to only update their location at the very end." So she is raidable under way, at the point
  // the day puts her — and the raid's receipt says it happened at sea.
  const raidedAtSea = HO187.resolveRaid(c2, h2, { cfg: C187.rules?.economy, dangerLevel: 9, day: 71, rng: () => 0 });
  check("§187: ⛔ a hull under way IS raidable — Erik overruled \"moving is not\", and the receipt says it happened at sea",
    raidedAtSea.atSea === true && !/nothing at anchor/.test(raidedAtSea.why || ""), JSON.stringify(raidedAtSea).slice(0, 200));
  const pos71 = CR187.voyagePosition(h2, { worldDay: 71, locations: L187 });
  const pos70 = CR187.voyagePosition(h2, { worldDay: 70, locations: L187 });
  check("§187: ⛔ …and WHERE she is comes from the day — a day out of Keelmouth she has covered half the two-day run, and the position moves with the date",
    pos70.fraction === 0 && Math.abs(pos71.fraction - 0.5) < 0.001 && pos71.daysOut === 1 && Math.abs(pos71.daysLeft - 1) < 0.001
    && pos71.worldPos && Math.abs(pos71.worldPos.colatitude - (51.75 + 47.75) / 2) < 0.01, JSON.stringify({ f70: pos70.fraction, f71: pos71.fraction, at: pos71.worldPos }));
  const wh = CR187.whereaboutsOf(h2, { worldDay: 71, locations: L187 });
  check("§187: ⛔ …and everything that asks where she is gets the nearest place to that point, with `atSea` said — while a holding at anchor answers with its own place, unchanged",
    wh.atSea === true && !!wh.locationId && ["keelmouth", "firstsight"].includes(wh.locationId)
    && CR187.whereaboutsOf(ship(), { worldDay: 71, locations: L187 }).atSea === false && CR187.whereaboutsOf(ship(), { worldDay: 71, locations: L187 }).locationId === "keelmouth", JSON.stringify(wh));
  check("§187: …and the line a player reads names both ends and the days either side", /out of Keelmouth/.test(CR187.voyageLine(h2, { worldDay: 71, locations: L187 }) || "") && /to Firstsight/.test(CR187.voyageLine(h2, { worldDay: 71, locations: L187 }) || ""), CR187.voyageLine(h2, { worldDay: 71, locations: L187 }));
  check("§187: ⛔ the tick reads her whereabouts, so the danger under her is where she IS and not where she left",
    /const whereNow = whereaboutsOf\(h, \{ worldDay:/.test(rd("engine/worldtick.js")) && /const loc = content\?\.locations\?\.\[whereNow\.locationId\]/.test(rd("engine/worldtick.js")));
  // ⛔ AND THE SAME RULE FOR A CARAVAN: the danger it meets today is the step of the road it is on today, not the worst of the route
  const CV187 = await import("../engine/caravan.js");
  const car187 = { id: "c", path: ["keelmouth", "firstsight", "longshore"], days: 6, departedDay: 40, danger: 9 };
  const steps = [40, 42, 43, 46].map(d => CV187.positionOnRoad(car187, d, L187));
  check("§187: ⛔ a caravan's danger is where it is on the day — the road's steps in order, each carrying its own place's danger, not the worst step of the whole route",
    steps.map(s => s.placeId).join(",") === "keelmouth,keelmouth,firstsight,longshore"   // three places over six days: on day 42 she is still short of the second && steps[0].daysOut === 0 && steps[3].daysLeft === 0
    && /the danger WHERE THEY ARE on this day/.test(rd("engine/caravan.js")) && /const at = positionOnRoad\(car, now - \(elapsed - 1 - i\), locations\);/.test(rd("engine/caravan.js")),
    JSON.stringify(steps.map(s => s.placeId)));
  check("§187: …and the hazard READS the place it happened at rather than being handed it and dropping it",
    /where = null \} = \{\}\) \{/.test(rd("engine/caravan.js")) && /const atWhere = where\?\.name \? ` near \$\{where\.name\}` : ""/.test(rd("engine/caravan.js")) && /set upon\$\{atWhere\}/.test(rd("engine/caravan.js")));
  // the world brings her in, not a moment sooner
  // ⛔ THE ORDER MATTERS AND MY FIRST VERSION GOT IT WRONG: both ticks run before the check does, so where she is had to be read
  // BETWEEN them, or the assertion asks where she is after she has already arrived.
  const early = CR187.voyageTick(c2, { worldDay: 71, cfg: cfg187 });
  const stillAt = h2.locationId;
  const onTime = CR187.voyageTick(c2, { worldDay: 72, cfg: cfg187 });
  check("§187: ⛔ the world brings her in on her day and not before — one arrival, said once, and the place is written then",
    early.arrived.length === 0 && stillAt === "keelmouth" && onTime.arrived.length === 1 && h2.locationId === "firstsight" && !CR187.voyageOf(h2)
    && onTime.notes.some(n => /has come in at firstsight/.test(n)) && CR187.voyageTick(c2, { worldDay: 99, cfg: cfg187 }).arrived.length === 0,
    JSON.stringify({ early: early.arrived.length, onTime: onTime.notes }));
  // ⛔ WILLED: the bearer decides, and if their standing falls far enough the holding walks away
  const dragon = () => ({ id: "the-grove", kind: "post", name: "the walking grove", locationId: "keelmouth", garrison: [], features: [], history: [], carriage: { moves: "willed", speed: 1, bearerId: "tolvess" } });
  const withBearer = (rel, status = "active") => mk(dragon(), { npcRegistry: { tolvess: { id: "tolvess", name: "Tolvess", relationship: rel, status } } });
  const warm = withBearer(6), cool = withBearer(0), done187 = withBearer(-9);
  check("§187: ⛔ a willed carriage asks its BEARER — willing at standing 6, refusing at 0, and the refusal is in their name",
    CR187.canSail(warm, warm.holdings[0], "firstsight", { locations: L187, cfg: cfg187, routeDays: 4 }).ok === true
    && CR187.canSail(cool, cool.holdings[0], "firstsight", { locations: L187, cfg: cfg187, routeDays: 4 }).ok === false
    && /Tolvess will not carry you/.test(CR187.canSail(cool, cool.holdings[0], "firstsight", { locations: L187, cfg: cfg187, routeDays: 4 }).why));
  const walked = CR187.voyageTick(done187, { cfg: cfg187 });
  check("§187: ⛔ …and once their standing falls past the floor THE HOLDING WALKS AWAY, with the reason on the record — a place with opinions, not a punishment",
    walked.departed.length === 1 && done187.holdings[0].condition === "gone" && /carried you as far as they cared to/.test(walked.notes[0] || "")
    && done187.holdings[0].history.some(l => /left:/.test(l)), JSON.stringify(walked));
  check("§187: …a bearer who is gone stops carrying it too", CR187.bearerWill({ moves: "willed", bearerId: "t" }, { t: { id: "t", name: "T", relationship: 9, status: "dead" } }, cfg187).leaves === true);
  // ⛔ WHAT CAN RIDE, AND WHAT EARNS AT SEA — Aevi's §4 list and her Q1, in content
  const laden = ship(); laden.features = [{ kind: "fishery" }, { kind: "market" }, { kind: "mine" }, { kind: "smithy" }];
  const ruling = CR187.featureRuling(laden, kinds187);
  check("§187: ⛔ a mine cannot ride and a fishery can; a fishery earns under way and a market does not (a market needs someone to sell TO)",
    ruling.grounded.map(f => f.kind).join() === "mine" && ruling.rides.map(f => f.kind).sort().join() === "fishery,market,smithy"
    && ruling.underWay.map(f => f.kind).sort().join() === "fishery,smithy" && ruling.earnsAtSea === true, JSON.stringify({ grounded: ruling.grounded.length, rides: ruling.rides.length, underWay: ruling.underWay.length }));
  check("§187: …and building one aboard is refused with its reason, while a holding that does not move takes anything",
    CR187.canBuildOn(ship(), "mine", kinds187).ok === false && /cannot be built aboard something that moves/.test(CR187.canBuildOn(ship(), "mine", kinds187).why)
    && CR187.canBuildOn(ship(), "fishery", kinds187).ok === true && CR187.canBuildOn({ id: "post" }, "mine", kinds187).ok === true);
  check("§187: the dials are content — the water tags, the willing floor and the leaving floor are Aevi's and Erik's to move",
    Array.isArray(cfg187?.needsTags?.crewed) && cfg187.needsTags.crewed.includes("harbour") && cfg187.needsTags.crewed.includes("river")
    && cfg187.willingAt === 1 && cfg187.leavesAt === -4 && /tags/.test(String(cfg187._why)));
  // ⛔ THE READERS: the page sails her, the world brings her in, the GM may give a carriage and may sail it
  const app187 = rd("app.js").replace(/^\s*\/\/.*$/gm, "");
  check("§187: ⛔ the page reads it — the card says what she is and where, the control sails her, and a refusal is SAID not swallowed",
    /const car = carriageOf\(h\); const voy = voyageOf\(h\);/.test(app187) && /data-hold-sail=/.test(app187) && /const r = sailHolding\(character, h, to, \{/.test(app187)
    && /stays where she is — \$\{r\.why\}/.test(app187) && /character\.currentLocationId = to; advanceClock/.test(app187));
  check("§187: ⛔ the world brings her in on the pass that already advances holdings, and says so as news",
    /voyageTick\(character, \{ worldDay: absoluteWorldDay\(now\)/.test(rd("engine/worldtick.js")) && /for \(const n of vt\.notes\) news\.push\(stampNews\(n,/.test(rd("engine/worldtick.js")));
  check("§187: ⛔ the GM has both ops with their contract, and a willed carriage records the bearer as steward — you hold it WITH them",
    /carriage\|sail/.test(rd("engine/gm.js")) && /a hold that MOVES/.test(rd("engine/gm.js"))
    && /else if \(kind === "carriage"\)/.test(app187) && /else if \(kind === "sail"\)/.test(app187) && /h\.steward = op\.carriage\.bearerId/.test(app187));
}

/* ══════════ §14 — THE FOLD CANNOT BEAT AN IMMUNITY THE BLOW COULD NOT ══════════ */
// ⛔ FOUND BY RUNNING AEVI'S TWELVE CRAFTS THROUGH A MELEE-SCALE FIGHT (CCODE-313), which is the whole
// reason Erik asked for a big-battle test. A physical-immune foe took ZERO from the player's typed blow and
// SIX from the folded party's contribution to that same blow — while the receipt still said affinity
// "immune". ⚠️ AN IMMUNITY THAT REPORTS ITSELF AND DOES NOTHING IS WORSE THAN NO IMMUNITY.
console.log("\n── §14 · the folded party answers the blow's affinity ──");
{
  const SBx = await import("../engine/skill_battle.js");
  const rulesX = rj("content/packs/core/rules/resolution.json");
  const sbX = rj("content/packs/core/rules/skill_battle_system.json").engine;
  const stepsX = rj("content/packs/core/rules/intensity_scaling.json").steps;
  const mkRng = () => { let s2 = 20260829; return () => { s2 |= 0; s2 = (s2 + 0x6D2B79F5) | 0; let t = Math.imul(s2 ^ (s2 >>> 15), 1 | s2); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
  const shX = (o = {}) => ({ attributes: { physical: 5, mental: 5, social: 5, practical: 5 }, energy: 200, health: 60, skills: [], ...o });
  const blow = { function: "strike", tier: 4, attribute: "physical", intensity: "standard", name: "x", mechanic: { damageType: "physical" }, functions: ["strike"] };
  const foldX = [1, 2, 3].map(i => ({ id: "f" + i, name: "S" + i, present: true, contributions: ["HARM", "MARTIAL"], sheet: shX() }));
  const go = (aff) => SBx.battleRound({ playerDecl: blow, oppDecl: { function: "shield", tier: 1, name: "g" },
    playerSheet: shX(), oppSheet: shX({ affinities: aff }), state: { momentum: 0, round: 1 },
    rules: rulesX, sb: sbX, steps: stepsX, rng: mkRng(), folded: foldX });
  const imm = go({ physical: "immune" }), open = go({});
  // ⛔ NON-VACUITY: the fold must still add when nothing blocks it, or this "fix" is just a deletion.
  check("§14: a folded party still adds to a blow nothing resists", (open?.damage?.melee?.added || 0) > 0, String(open?.damage?.melee?.added));
  check("§14: …and adds NOTHING to a blow the target is immune to", !imm?.damage?.melee && imm?.damage?.amount === 0,
    `amount=${imm?.damage?.amount} melee=${JSON.stringify(imm?.damage?.melee || null)}`);
}

/* ══════════ §15 — AN UNTYPED BLOW ANNOUNCES ITSELF ══════════ */
// ⛔ ERIK 2026-08-30: "untyped can default to physical for now if that's the way we have it set up... BUT IT
// STILL NEEDS A FLAG SO WE CAN FIND AND TYPE THE DAMAGE."
//
// ⚠️ A DEFAULT THAT LEAVES NO TRACE IS A DEFECT THAT LOOKS LIKE A DESIGN. Two different things happen and
// both used to be silent: a MUNDANE blow taking the `untypedIs` fallback (Erik's rule, working), and a
// craft resolving to NO KIND AT ALL — which is invisible to every affinity in the game.
console.log("\n── §15 · untyped damage is findable ──");
{
  const SBz = await import("../engine/skill_battle.js");
  const rulesZ = rj("content/packs/core/rules/resolution.json");
  const sbZ = rj("content/packs/core/rules/skill_battle_system.json").engine;
  const stepsZ = rj("content/packs/core/rules/intensity_scaling.json").steps;
  const rngZ = () => { let s3 = 20260830; return () => { s3 |= 0; s3 = (s3 + 0x6D2B79F5) | 0; let t = Math.imul(s3 ^ (s3 >>> 15), 1 | s3); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
  const shZ = (o = {}) => ({ attributes: { physical: 6, mental: 6, social: 6, practical: 6 }, energy: 200, health: 80, skills: [], ...o });
  const go = (d) => SBz.battleRound({ playerDecl: d, oppDecl: { function: "shield", tier: 1, name: "g" },
    playerSheet: shZ(), oppSheet: shZ(), state: { momentum: 0, round: 1 },
    rules: rulesZ, sb: sbZ, steps: stepsZ, rng: rngZ() })?.damage || {};

  const typed = go({ function: "strike", tier: 5, attribute: "physical", intensity: "standard", name: "t", mechanic: { damageType: "heat" }, functions: ["strike"] });
  const mundane = go({ function: "strike", tier: 5, attribute: "physical", intensity: "standard", name: "m", functions: ["strike"] });
  const undecided = go({ function: "strike", tier: 5, attribute: "physical", intensity: "standard", name: "u", tradition: "cogitant", functions: ["strike"] });

  // ⛔ NON-VACUITY FIRST: a craft that names its kind must carry NEITHER flag, or they mean nothing.
  check("§15: a typed craft carries no flag", typed.damageType === "heat" && !typed.typedByDefault && !typed.untyped);
  // ✅ ERIK'S RULE, WORKING AND VISIBLE — a sword is physical, and the receipt says it was defaulted.
  check("§15: a MUNDANE blow defaults to physical AND says so", mundane.damageType === "physical" && mundane.typedByDefault === true);
  // ⛔ THE ONE THE FLAG IS FOR. A craft with a tradition and no kind is UNDECIDED, not mundane — and it is
  // invisible to every affinity, so it must be findable at the moment it happens.
  check("§15: a craft with a tradition and no kind is flagged UNTYPED", undecided.untyped === true && !undecided.damageType,
    JSON.stringify({ type: undecided.damageType, untyped: undecided.untyped }));
}

/* ══════════ §16 — CRAFT AND CREATURE AGREE ABOUT HAVING A SELF ══════════ */
// ⛔ AEVI: "every craft that says 'nothing without a self' should agree with every creature that has none.
// Right now that agreement is prose on both sides." ⚠️ SIX CRAFTS STATED THE RULE IN FOUR PHRASINGS.
// ⛔ ERIK'S TEST FOR THE FIELD, WHICH IT HAD TO PASS: does it let content say ONCE what it currently says
// many times in prose? This gate is what makes the once BINDING.
console.log("\n── §16 · craft and creature agree about having a self ──");
{
  const SBs = await import("../engine/skill_battle.js");
  const best = rj("content/packs/valley/bestiary.json");
  const classes = best.classes || {};
  const selfless = Object.entries(classes).filter(([, v]) => v && typeof v === "object" && v.hasSelf === false).map(([k]) => k);
  const selfed = Object.entries(classes).filter(([, v]) => v && typeof v === "object" && v.hasSelf === true).map(([k]) => k);

  // ⛔ EVERY CLASS DECLARES, OR THE PROPERTY IS DECORATION. A bare string class (which is what
  // `narrowed_dead` was before 2026-08-30) reads as undefined to every consumer.
  const undeclared = Object.entries(classes)
    .filter(([k]) => !k.startsWith("_"))
    .filter(([, v]) => !(v && typeof v === "object" && typeof v.hasSelf === "boolean")).map(([k]) => k);
  check("§16: every creature class declares hasSelf as a boolean", undeclared.length === 0, undeclared.join(", "));
  // ⚠️ NON-VACUITY, BOTH SIDES: without one of each the agreement below is trivially true.
  check("§16: the corpus has classes WITH and WITHOUT a self",
    selfless.length > 0 && selfed.length > 0, `with: ${selfed.length}, without: ${selfless.length}`);

  // ⛔ AND THE CRAFTS THAT NEED ONE.
  const needSelf = [];
  for (const dir of ["content/packs/core/abilities"]) {
    for (const f of readdirSync(join(root, dir)).filter(x => x.endsWith(".json"))) {
      const doc = rj(`${dir}/${f}`);
      for (const a of (doc.abilities || [])) {
        if (a && JSON.stringify(a).includes('"requiresSelf"')) needSelf.push(a);
      }
    }
  }
  check("§16: some craft actually requires a self (non-vacuity)", needSelf.length >= 3, `${needSelf.length} crafts`);

  // ⛔ THE AGREEMENT ITSELF, ASSERTED THROUGH THE ENGINE RATHER THAN BY READING BOTH FILES. A gate that
  // compared two JSON files would pass while the rule did nothing in play — which is the whole failure
  // this field exists to end.
  const bad = [];
  for (const a of needSelf) {
    const decl = { ...a, function: (a.functions || [])[0], rank: 1 };
    for (const cls of selfless) {
      if (!SBs.selfBlocked(decl, { creatureClass: cls }, { classes })) bad.push(`${a.id} vs ${cls}`);
    }
    // ✅ AND IT MUST STILL REACH A THING THAT HAS ONE, or the craft is simply broken.
    for (const cls of selfed) {
      if (SBs.selfBlocked(decl, { creatureClass: cls }, { classes })) bad.push(`${a.id} wrongly blocked vs ${cls}`);
    }
  }
  check("§16: every craft requiring a self is blocked by every selfless class, and by no other",
    bad.length === 0, bad.slice(0, 6).join(" · "));

  // ⚠️ ABSENT IS NOT FALSE — an unclassed creature is not quietly immune to half the catalogue.
  check("§16: an unclassed creature is NOT blocked (absent is not false)",
    needSelf.length ? !SBs.selfBlocked({ ...needSelf[0], function: (needSelf[0].functions || [])[0] }, {}, { classes }) : false);
}

/* ══════════ §17 — SNG-268: THE BRAID GENERATOR CAN SEE THE RING ══════════ */
// ⛔ THE SPEC'S OWN TEST OF DONE, run as a gate: "mint one adjacent and one antipodal braid. The antipodal
// must cost visibly more AND carry a tension bound; the adjacent must carry neither. Identical output =
// the generator still cannot see the ring."
//
// ⚠️ AND ONE CORRECTION TO THE SPEC, MEASURED BEFORE BUILDING ON IT: it says the scale is "0 same → 4
// antipodal". THIS RING IS 24 WIDE AND ITS MAXIMUM DISTANCE IS 12. The three authored braids it cites as
// evidence — meaning_engine, harbored_flame, the_turning_word — are all distance 12, which confirms the
// EVIDENCE while correcting the SCALE.
console.log("\n── §17 · a braid knows how far apart its parents are ──");
{
  const BR = await import("../engine/braids.js");
  const TR = await import("../engine/traditions.js");
  const idx = TR.buildTraditionIndex(rj("content/packs/core/rules/traditions.json"));
  const cat = {
    A: { id: "A", name: "Ash", tradition: "umbral", energyCost: 6, functions: ["strike"], levelReq: 3 },
    B: { id: "B", name: "Flame", tradition: "blazeborn", energyCost: 4, functions: ["strike"], levelReq: 3 },
    V: { id: "V", name: "Veil", tradition: "veilwright", energyCost: 4, functions: ["strike"], levelReq: 3 },
  };
  const ch = { level: 9, abilities: [{ abilityId: "A", rank: 3 }, { abilityId: "B", rank: 3 }, { abilityId: "V", rank: 3 }] };
  const near = BR.buildBraidDef(ch, ["A", "V"], cat, { traditionIndex: idx });   // umbral × veilwright — d1
  const far = BR.buildBraidDef(ch, ["A", "B"], cat, { traditionIndex: idx });    // umbral × blazeborn — d12

  // ⛔ THE THREE AUTHORED BRAIDS ARE ANTIPODES — the spec's evidence, re-measured rather than trusted.
  for (const [a, b] of [["enginewright", "numinous"], ["umbral", "blazeborn"], ["threnodist", "syllogist"]]) {
    check(`§17: the authored braid ${a}×${b} is antipodal`, TR.ringDistance(a, b, idx) === 12);
  }
  check("§17: an ANTIPODAL braid costs visibly more than an adjacent one",
    far.energyCost > near.energyCost, `${far.energyCost} vs ${near.energyCost}`);
  check("§17: …and carries the tension bound", !!far.tensionNote);
  // ⛔ THE OTHER HALF, WHICH IS WHAT MAKES IT A DISTINCTION: adjacent gets neither.
  check("§17: an ADJACENT braid carries NO tension bound", !near.tensionNote);
  check("§17: the band is recorded on the mint receipt",
    far.minted?.tension?.band === "antipodal" && near.minted?.tension?.band === "adjacent");
  // ✅ SNG-268 §4 — dual-pole gating stops being a three-instance category.
  check("§17: a minted braid declares requiresPoles from its own parents",
    (far.minted?.requiresPoles || []).length === 2 && far.minted.requiresPoles.includes("umbral"));
  // ⚠️ ABSENT IS TODAY: with no index, byte-identical to what shipped.
  const blind = BR.buildBraidDef(ch, ["A", "B"], cat, {});
  check("§17: without a tradition index nothing changes (absent is not zero)",
    !blind.tensionNote && blind.energyCost < far.energyCost, `${blind.energyCost}`);
  // ⛔ AND THE LIVE PATH SUPPLIES IT, or the whole thing is inert.
  check("§17: app.js threads the tradition index into the braid builder",
    rd("app.js").includes("traditionIndex: CONTENT.traditionIndex"));
}

/* ══════════ §18 — A MENDING CAN BE AIMED, AND SOME THINGS ARE BURNED BY IT ══════════ */
// ⛔ ERIK 2026-08-30: "the intent is to be able to heal anyone you want, or use healing on any target."
// ⚠️ A HEAL WAS SPENT ON ITS OWN SIDE, ALWAYS — one line decided it and nothing could ask, which is why
// backlog P3 (heal → decay on an undead) had NO PATH TO FIRE. The rule was never the hard part.
//
// ✅ AND P3 NEEDS NO UNDEAD FLAG. Aevi typed 25 healing crafts `vitality`; `the_narrowed` is authored
// `vitality: vulnerable`. The inversion falls out of what the creature ALREADY SAYS ABOUT ITSELF.
console.log("\n── §18 · a mending can be aimed, and some things are burned by it ──");
{
  const SBh = await import("../engine/skill_battle.js");
  const rulesH = { ...rj("content/packs/core/rules/resolution.json"), craftMechanics: rj("content/packs/core/rules/craft_mechanics.json") };
  const sbH = rj("content/packs/core/rules/skill_battle_system.json").engine;
  const stepsH = rj("content/packs/core/rules/intensity_scaling.json").steps;
  const narrowed = (rj("content/packs/valley/bestiary.json").roster || []).find(c => c.id === "the_narrowed");
  const rngH = () => { let z = 20260830; return () => { z |= 0; z = (z + 0x6D2B79F5) | 0; let t = Math.imul(z ^ (z >>> 15), 1 | z); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
  const shH = (o = {}) => ({ attributes: { physical: 7, mental: 7, social: 7, practical: 7 }, energy: 300, health: 60, maxHealth: 100, skills: [], ...o });
  const mend = { function: "mend", tier: 6, attribute: "mental", intensity: "standard", name: "a mending", functions: ["mend"], mechanic: { damageType: "vitality" } };
  const alliesH = [{ id: "char-me", name: "You", isPlayer: true, present: true, sheet: shH() },
    { id: "sprig", name: "Sprig", present: true, sheet: shH({ health: 20 }) }];
  const go = (target, opp) => SBh.battleRound({ playerDecl: mend, oppDecl: { function: "strike", tier: 1, name: "swing" },
    playerSheet: shH(), oppSheet: opp || shH(), state: { momentum: 0, round: 1 },
    rules: rulesH, sb: sbH, steps: stepsH, rng: rngH(), allies: alliesH, healTarget: target })?.healing || {};

  const own = go(null), ally = go("sprig"), foe = go("opponent");
  const undead = go("opponent", shH({ affinity: narrowed?.affinity || {} }));

  // ⛔ NON-VACUITY FIRST: the unaimed case must still heal, or every row below is a broken heal.
  check("§18: unaimed, a mending still heals the caster (unchanged)", own.amount > 0 && own.side === "player", JSON.stringify(own.amount));
  check("§18: it can be aimed at an ALLY, and the side follows the subject",
    ally.amount > 0 && ally.side === "ally" && ally.onId === "sprig", `${ally.amount} on ${ally.onId}`);
  check("§18: it can be aimed at the FOE", foe.amount > 0 && foe.side === "opponent");
  // ⛔ BACKLOG P3, AND IT NEEDED NO NEW RULE — only a heal that could be aimed at something hostile.
  check("§18: mending a thing VULNERABLE to vitality HARMS it",
    undead.amount < 0 && undead.inverted === true && undead.affinity === "vulnerable",
    JSON.stringify({ amount: undead.amount, aff: undead.affinity }));
  // ⚠️ AND THE PLAYER CAN ACTUALLY ASK — the affordance, without which this is a rule nobody reaches.
  check("§18: the interface asks who the mending is for", rd("app.js").includes("data-sbheal"));
  check("§18: …and the encounter forwards the pick", rd("engine/encounters.js").includes("healTarget: state.healTarget"));
}

/* ══════════ §19 — THE FOLD CAN FALL, AND IT FALLS BY THE ENEMY'S INTENT ══════════ */
// ⛔ TWO FIXES THAT ONLY WORK TOGETHER, AND EACH PROVES THE OTHER.
//   CCODE-319  the pool is PROPORTIONAL TO HEALTH. It was `per × K` and named no level while health is
//              `level × 2`, so it was in range at level 1–2 and DEAD from level 3 to 100.
//   CCODE-318  the fold hears the ENEMY'S INTENT. Softest-first was the only rule, so the aggregate played
//              every foe as if it were hunting your healer.
// ⚠️ THE ORDERING FIX WAS UNOBSERVABLE UNTIL THE POOL FIRED — I could not verify CCODE-318 at all until
// CCODE-319 landed, which is why they ship together.
console.log("\n── §19 · the fold can fall, and it falls by the enemy's intent ──");
{
  const SBf = await import("../engine/skill_battle.js");
  const rulesF = rj("content/packs/core/rules/resolution.json");
  const sbF = rj("content/packs/core/rules/skill_battle_system.json").engine;
  const stepsF = rj("content/packs/core/rules/intensity_scaling.json").steps;
  const shF = (o = {}) => ({ attributes: { physical: 6, mental: 6, social: 6, practical: 6 }, energy: 200, health: 14, skills: [], ...o });
  const fold = () => [
    { id: "sprig", name: "Sprig", present: true, contributions: ["RESTORE"], sheet: shF({ soak: 0, attributes: { physical: 1 } }) },
    ...[1, 2, 3, 4].map(i => ({ id: "sp" + i, name: "Spear" + i, present: true, contributions: ["HARM", "MARTIAL"], sheet: shF({ soak: 5 }) })),
  ];
  const run = (policy, T = 300) => {
    let fell = 0, mender = 0;
    for (let t = 0; t < T; t++) {
      let z = t * 7919 + 11;
      const rngF = () => { z |= 0; z = (z + 0x6D2B79F5) | 0; let q = Math.imul(z ^ (z >>> 15), 1 | z); q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q; return ((q ^ (q >>> 14)) >>> 0) / 4294967296; };
      const r = SBf.battleRound({ playerDecl: { function: "reveal", tier: 1, name: "look" },
        oppDecl: { function: "strike", tier: 9, attribute: "physical", intensity: "surge", name: "swing" },
        playerSheet: shF({ health: 80 }), oppSheet: shF({ attributes: { physical: 9, mental: 9, social: 9, practical: 9 } }),
        state: { momentum: 0, round: 1 }, rules: rulesF, sb: sbF, steps: stepsF, rng: rngF, folded: fold(), targetPolicy: policy });
      for (const l of (r.damage?.foldedLosses?.downed || [])) { fell++; if (l.id === "sprig") mender++; }
    }
    return { fell: fell / T, mender: mender / T };
  };
  const threat = run("threat"), hunter = run("healer");

  // ⛔ CCODE-319 FIRST: without this the mechanic cannot fire at all and every row below is vacuous.
  check("§19: a folded ally can actually fall", threat.fell > 0, `${threat.fell.toFixed(2)} losses/round`);
  // ⛔ CCODE-318: a brute that fights whoever fights it does NOT hunt the mender.
  check("§19: a THREAT-seeking foe does not take the mender", threat.mender === 0, `${(threat.mender * 100).toFixed(0)}%`);
  // ✅ AND A HUNTER STILL DOES — or the fix has simply disarmed the enemy rather than given it intent.
  check("§19: a HEALER-hunting foe still takes her", hunter.mender > 0, `${(hunter.mender * 100).toFixed(0)}%`);
  // ⚠️ THE ORDERING CHANGES WHO, NEVER HOW MANY — the claim CCODE-308 made, asserted rather than trusted.
  check("§19: the casualty COUNT is the same either way", Math.abs(threat.fell - hunter.fell) < 0.05,
    `${threat.fell.toFixed(2)} vs ${hunter.fell.toFixed(2)}`);
  // ⛔ AND THE DIAL IS CONTENT, not a constant in the engine.
  check("§19: the pool's scale is a content dial", Number(sbF?.melee?.foldedPoolPerHealth) >= 2,
    String(sbF?.melee?.foldedPoolPerHealth));
}

/* ══════════ §20 — WHAT YOUR LINE COVERS IS ON THE SCREEN ══════════ */
// ⛔ `groupCapability` computed coverage · depth · sole · cohesion since CCODE-307 and NOTHING IN THE GAME
