    const idx54 = rd("docs/RULINGS.md");
    const builtNums = new Set([...idx54.matchAll(/^\|\s*~{0,2}\*\*R(\d+)\*\*~{0,2}\s*\|[^\n]*?\|\s*✅/gm)].map(m => Number(m[1])));
    const builtAbsent = [...builtNums].filter(n => !hasR(doc, n)).sort((a, b) => a - b);
