  const { def: def71, oppSheet: os71, state: st71 } = BT71.duelFromTarget(pc71, { id: "veth-ondra", name: veth71.name }, { catalog: C71.abilities, npcs: C71.npcs, cfg: cfg71, day: 1, sb: sb71, here: null });
