    g && g.passesPerClimb === 4 && !g.ceilingByKeeperTier && g.floorByKeeperTier?.notable === "holding" && g.floorByKeeperTier?.epic === "thriving" && Array.isArray(g.improveFunctions) && g.improveFunctions.includes("mend")
