  const passes = (c, n) => { let last = null; for (let i = 0; i < n; i++) last = H74.growHolding(c, c.holdings[0], { cfg: cfgS, npcs: {}, npcCfg, worldCount: 100 + i, nameOf: (x) => "Keeper" }); return last; };
