  const w = JB321.jobWages(ch, team, { backAtHours: 100 + 7 * 24 }, { wagePerHand: 3, nowHours: 100 });
  const none = JB321.jobWages(ch, [{ id: "pell" }, { id: "player", isYou: true }], { backAtHours: 400 }, { wagePerHand: 3, nowHours: 100 });
