{
  const M322 = await import("../engine/money.js");
  const { reconcile: rec322 } = await import("../engine/reconcile.js");
  const { loadContentHeadless: lch322 } = await import("./headless_content.mjs");
  const CT322 = await lch322();
  const S = M322.STARTING_PURSE_SPEC;
  const tiers = Object.values(S.byBackground);
  check("§322: ⛔ LIQUIDITY, NOT APPROVAL — forty backgrounds on the four worthBands rungs (0 · 4 · 15 · 50), every one below well-found; the smuggler sits with the trader and the devotee with the orphan; an unnamed background is ASKED",
    Object.keys(S.byBackground).length === 40 && tiers.filter(t => t === "L3").length === 3 && tiers.filter(t => t === "L0").length === 7
    && M322.startingPurseFloor("smuggler") === M322.startingPurseFloor("trader") && M322.startingPurseFloor("devotee") === M322.startingPurseFloor("orphan")
    && M322.startingPurseFloor("trader") === 50 && M322.startingPurseFloor("warden") === 4 && M322.startingPurseFloor("medic") === null
    && Object.values(S.rungs).every(v => v < 60));
  const mk = (o) => ({ id: "fx", name: "Fx", reconcileVersion: 70, worldState: {}, purse: { crystal: 0, coin: 0, paper: 0, marks: 0, scrip: {} }, deeds: [], ...o });
  const deeds = (n) => Array.from({ length: n }, (_, i) => ({ what: `d${i}` }));
  const a = mk({ background: "war_leader", deeds: deeds(2), currentLocationId: "the_crossing" }); const ra = rec322(a, "character", { content: CT322 });
  const b = mk({ background: "precursor_marked", deeds: deeds(8), currentLocationId: "millbrook", purse: { crystal: 31, coin: 0, paper: 0, marks: 0, scrip: {} } }); rec322(b, "character", { content: CT322 });
  const numinous = Object.values(CT322.locations).find(l => l.regionId === "the_numinous_reach");
  const c = mk({ background: "orphan", deeds: deeds(11), currentLocationId: numinous?.id }); rec322(c, "character", { content: CT322 });
  check("§322: ⛔ THE FLOOR IS max(), THE SETTLEMENT IS +, BOTH BY PLACE — two lines; a purse above its floor gets only the deeds; a Reach pays its scrip",
    // ⚠️ CCODE-483: THIS COUNTED EVERY NOTE THE WHOLE RECONCILE WROTE (`notes.length === 2`) for a sentence
    // that is about the PURSE'S two lines. It went red the day a later step — what you have heard of the powers
    // — also had something to say, which is a gate pinning its neighbours rather than its subject.
    a.purse.crystal === 15 + 16 && (ra.notes || []).filter(n => /purse|arrears/i.test(n)).length === 2 && /starting purse you were owed/.test(ra.notes.join(" ")) && /arrears for 2 deeds/.test(ra.notes.join(" "))
    && b.purse.crystal === 31 + 64 && c.purse.crystal === 0 && c.purse.scrip.the_numinous_reach === M322.incomeHere(88, "the_numinous_reach", CT322.rules.economy).amount,
    JSON.stringify({ a: a.purse, b: b.purse, c: c.purse }));
  const silas = mk({ id: "char-mrhs8286", background: "lineage_taught", deeds: deeds(52), currentLocationId: "millbrook" }); rec322(silas, "character", { content: CT322 });
  const asked = mk({ background: "medic", deeds: deeds(5), currentLocationId: "millbrook" }); rec322(asked, "character", { content: CT322 });
  const again = JSON.parse(JSON.stringify(a)); const before = again.purse.crystal; rec322(again, "character", { content: CT322 });
  check("§322: ⛔ SILAS IS UNTOUCHED (settled at R48); a background the table does not name gets the deeds and is asked for the floor; and it runs ONCE",
    silas.purse.crystal === 0 && asked.purse.crystal === 40 && asked.worldState.purseFloorAsked === "medic" && again.purse.crystal === before && again.reconcileVersion >= 71);
  const A322 = rd("app.js").replace(/\r\n/g, "\n").split("\n").filter(l => !/^\s*\/\//.test(l)).join("\n");
  check("§322: ⛑ a new character is born current, so the purse is paid at birth — what the background carried, in the money of where it begins",
    /character\.reconcileVersion = topReconcileVersion\("character"\);[\s\S]{0,400}const f443 = startingPurseFloor\(character\.background, CONTENT\.rules\?\.economy \|\| null\);\n\s*if \(f443 > 0\) earnAt\(character, f443,/.test(A322));
}

// ══════════ §323 · CCODE-444 — A HOLD KEEPS VALUABLES, AND EVERY WELL AND SINK CAN BE SWITCHED ══════════
// Erik: "we should be able to have valuable items stored in a holding - I'm thinking about mobile energy wells and sinks, valuable statues,
// artifacts, etc." — picking that a stored one works where it is kept — and "we also need to allow the sinks and wells to be active or
// deactivated. The same for companion sink and well effects or other items."
console.log("\n── §323 · the vault, and the switch — a kept well works at its hold, a switched-off one moves nothing, and the charge is read through the catalogue ──");
{
  const H323 = await import("../engine/holdings.js");
  const SB323 = await import("../engine/substrate.js");
  const INV323 = await import("../engine/inventory.js");
  const CP323 = await import("../engine/companions.js");
  const { loadContentHeadless: lch323 } = await import("./headless_content.mjs");
  const CT323 = await lch323();
  const cat = CT323.items || {};
  const pc = { inventory: [] };
  INV323.addItem(pc, "waystaff", cat);
  const staff = pc.inventory[0];
  const on = SB323.carriedSubstrate(pc, cat, []), named = SB323.carriedSubstrateSources(pc, cat, []);
  staff.active = false;
  const off = SB323.carriedSubstrate(pc, cat, []), offNamed = SB323.carriedSubstrateSources(pc, cat, []);
  delete staff.active;
  check("§323: ⛔ THE DOOR — a Waystaff picked up from the catalogue moves the ground by its 0.18 (the pack's copy never carried the charge, so it moved it by 0 since SNG-090); switched off, it moves nothing and is not named",
    cat.waystaff?.substrateCharge === 0.18 && !("substrateCharge" in staff) && on === 0.18 && named.length === 1 && named[0].name === "Waystaff"
    && off === 0 && offNamed.length === 0, JSON.stringify({ on, off, named }));
  const aevi = CT323.companions?.aevi;
  const chr = { companions: ["aevi"], aurasOff: {} };
  const comps = CP323.activeCompanions(chr, CT323.companions);
  const auraOn = SB323.carriedSubstrate(chr, cat, comps);
  chr.aurasOff.aevi = true;
  const auraOff = SB323.carriedSubstrate(chr, cat, comps);
  const unit = { artifacts: [{ id: "waystaff", active: false }, { id: "prism_lens" }] };
  const u = SB323.unitCarriedSubstrate(unit, { items: cat, companions: CT323.companions, contingents: [{ npcId: "aevi" }], aurasOff: { aevi: true } });
  const gmStilled = CP323.companionsForGM(comps, chr, null) || "";
  check("§323: ⛔ A COMPANION'S AURA SWITCHES — stilled at the character's word it moves nothing, in the pack's term and in a column; a switched-off artifact moves a unit's ground by nothing; the GM is told it is stilled",
    Number(aevi?.substrateAura) === 0.2 && auraOn === 0.2 && auraOff === 0
    && u.total === cat.prism_lens.substrateCharge && u.sources.length === 1 && /Its aura is STILLED at the character's word/.test(gmStilled),
    JSON.stringify({ auraOn, auraOff, u: u.total }));
  const hold = { id: "h323", name: "Whistle Post", locationId: "ridge323", condition: "steady", features: [] };
  const who = { holdings: [hold], inventory: [] };
  INV323.addItem(who, "waystaff", cat);
  INV323.addItem(who, { name: "a marble saint", kind: "relic" }, cat);
  who.inventory.push({ id: null, name: "the sealed letter", kind: "quest", qty: 1 });
  const away = H323.depositToVault(who, "h323", ["Waystaff"], { hereId: "elsewhere" });
  const nowhere = H323.depositToVault(who, "h323", ["Waystaff"], { hereId: null });
  const put = H323.depositToVault(who, "h323", ["Waystaff", "a marble saint", "the sealed letter"], { hereId: "ridge323" });
  check("§323: ⛔ WHERE YOU STAND — away from the hold, and nowhere at all, the vault refuses; at it, whole stacks move out of the pack and a thing the story carries stays with you",
    !away.ok && !nowhere.ok && put.ok && put.moved.length === 2 && H323.vaultOf(hold).length === 2
    && who.inventory.length === 1 && who.inventory[0].kind === "quest", JSON.stringify({ away, nowhere, put, pack: who.inventory.map(i => i.name) }));
  const atHold = H323.holdingFieldDelta(who, "ridge323", null, { items: cat });
  const blind = H323.holdingFieldDelta(who, "ridge323", null);
  const src = H323.holdingFieldSources(who, "ridge323", null, { items: cat });
  const gm = H323.holdingsForGM(who, null, { hereId: "ridge323", items: cat }) || "";
  H323.vaultOf(hold)[0].active = false;
  const atHoldOff = H323.holdingFieldDelta(who, "ridge323", null, { items: cat });
  const gmOff = H323.holdingsForGM(who, null, { hereId: "ridge323", items: cat }) || "";
  check("§323: ⛔ A KEPT WELL WORKS WHERE IT IS KEPT (Erik's pick) — at the hold the Waystaff adds its 0.18, named in the receipt as kept there; nowhere else; switched off, nothing. The GM is told what the vault keeps and whether it is on",
    atHold === 0.18 && blind === 0 && H323.holdingFieldDelta(who, "elsewhere", null, { items: cat }) === 0 && atHoldOff === 0
    && src.length === 1 && src[0].name === "Waystaff, kept at Whistle Post" && src[0].kind === "vault"
    && /its vault keeps Waystaff \(a well, \+0\.18, on\), a marble saint/.test(gm) && /Waystaff \(a well, \+0\.18, off\)/.test(gmOff),
    JSON.stringify({ atHold, blind, atHoldOff, src, gm: gm.slice(-220) }));
  who.inventory = Array.from({ length: 30 }, (_, i) => ({ name: `pebble ${i}`, kind: "misc", qty: 1 }));
  const full = H323.withdrawFromVault(who, "h323", ["a marble saint"], { hereId: "ridge323" });
  who.inventory = [];
  const back = H323.withdrawFromVault(who, "h323", ["Waystaff"], { hereId: "ridge323" });
  const gmPack = INV323.inventoryForGM(who);
  check("§323: ⛑ TAKEN BACK where you stand — a full pack refuses rather than growing past addItem's 30; the Waystaff returns still switched off, and the GM is told it is",
    !full.ok && /your pack holds 30 things/.test(full.why) && back.ok && who.inventory.length === 1 && who.inventory[0].active === false
    && H323.vaultOf(hold).length === 1 && /SWITCHED OFF at the character's word/.test(gmPack), JSON.stringify({ full, back }));
  const A323 = rd("app.js").replace(/\r\n/g, "\n").split("\n").filter(l => !/^\s*\/\//.test(l)).join("\n");
  check("§323: ⛑ THE SCREEN AND THE ROLL — both ground readers hand the catalogue to the hold's field; the receipt names a hold's wells, sinks and kept charges; the vault, the item switch and the aura switch are wired",
    (A323.match(/holdingFieldDelta\(character, location\?\.id, holdCfgNow\(\), \{ items: CONTENT\.items \}\)/g) || []).length === 2
    && /verdict\.carriedBy = \[\.\.\.carriedSubstrateSources\(character, CONTENT\.items, comps\), \.\.\.holdingFieldSources\(/.test(A323)
    && /\[data-hold-vault\]"\)\) btn\.onclick = \(\) => showVaultDeposit\(/.test(A323) && /\[data-vault-take\]/.test(A323) && /\[data-vault-charge\]/.test(A323)
    && /\[data-item-charge\]"\)\) b\.onclick/.test(A323) && /\[data-aura-toggle\]"\)\) btn\.onclick/.test(A323));
}

// ══════════ §324 · CCODE-445 — THE ARMORY ══════════
// Erik: "we need an armory to store the weapons and armor for different troop types. Without getting too in depth about it, I could see
// swords, shields, axes, bows, crossbows, leather, plate, chain mail etc. These are probably something the hold can produce at the forge
// smithy etc. And would allow you to outfit units up to the quantity you have. You could sell them and send them to other holds, etc."
console.log("\n── §324 · the armory — the forge makes what the store can feed, hands are outfitted up to the stock, shields protect a lone band too, gear sells as arms ──");
{
  const AR = await import("../engine/armory.js");
  const ML = await import("../engine/melee.js");
  const FL = await import("../engine/fellowship.js");
  const H324 = await import("../engine/holdings.js");
  const { loadContentHeadless: lch324 } = await import("./headless_content.mjs");
  const CT324 = await lch324();
  const T = AR.armoryTable();
  const over = AR.armoryTable({ gear: { sword: { quality: 0.2 }, spear: { slot: "weapon", one: "spear", many: "spears", quality: 0.09, materials: { raw_material: 1 } } } });
  check("§324: ⚑ THE TABLE — Erik's eight (swords, axes, bows, crossbows, shields, leather, chain mail, plate) in three kinds of kit, every number a stand-in that an authored `economy.armory` overrides field by field",
    Object.keys(T.gear).length === 8 && ["sword", "axe", "bow", "crossbow", "shield", "leather", "chain", "plate"].every(k => T.gear[k])
    && new Set(Object.values(T.gear).map(g => g.slot)).size === 3 && /stand-in/.test(AR.ARMORY_DEFAULTS._standIn)
    && over.gear.sword.quality === 0.2 && over.gear.sword.many === "swords" && over.gear.spear?.slot === "weapon" && T.gear.shield.gives === "PROTECT");

  const hold = () => ({ id: "h324", name: "Fell Pell", locationId: "mill324", condition: "steady", store: { raw_material: 10 }, features: [{ kind: "forge" }, { kind: "smithy" }] });
  const who = { holdings: [hold()], bands: [] };
  const h = who.holdings[0];
  const bare = { holdings: [{ id: "bare", name: "Bare Post", locationId: "x", features: [{ kind: "watch" }] }] };
  const noForge = AR.setForgeOrder(bare, "bare", "sword", 5);
  const building = AR.makersAt({ features: [{ kind: "forge", building: true }] });
  const set = AR.setForgeOrder(who, "h324", "sword", 20);
  const p1 = AR.tickArmory(h), p2 = AR.tickArmory(h), p3 = AR.tickArmory(h), p4 = AR.tickArmory(h);
  check("§324: ⛔ THE FORGE — a forge and a smithy make 6 a pass from the store's raw material; the order and the store run down together; a stall is said ONCE; no forge, no order; a forge still being built makes nothing",
    !noForge.ok && building.cap === 0 && set.ok && AR.makersAt(h).cap === 6
    && p1.made === 6 && /Fell Pell made 6 swords — 14 to go\./.test(p1.said) && p2.made === 4 && h.store.raw_material === 0
    && p3.made === 0 && /no raw material left for swords/.test(p3.said) && p4.said === null && AR.gearCount(h, "sword") === 10 && h.forgeOrder.left === 10,
    JSON.stringify({ p1, p2, p3, p4, store: h.store, armory: h.armory }));
  const xb = hold(); xb.store = { raw_material: 5 };
  const whoX = { holdings: [xb] };
  AR.setForgeOrder(whoX, "h324", "crossbow", 4);
  const px = AR.tickArmory(xb);
  check("§324: ⛑ …and a crossbow's lock takes a part — with raw material and no parts, the forge says it is the parts that ran out",
    px.made === 0 && /no mech parts left for crossbows/.test(px.said || ""), JSON.stringify(px));

  h.armory = { sword: 10, shield: 12 };
  who.bands = [{ id: "b324", name: "Ridge Watch", condition: "fresh", contingents: [{ n: 20, quality: 1, does: ["HARM", "MARTIAL"] }, { n: 1, quality: 2, npcId: "pell", does: ["HARM"] }] }];
  const before = ML.bandStrength(ML.resolvedUnit(who.bands, who.bands[0]), {}).effective;
  const gapsBefore = ML.bandGaps(who.bands[0], {}).map(g => g.missing);
  const away = AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "weapon", gear: "sword", holdId: "h324", hereId: "elsewhere" });
  const named = AR.outfitContingent(who, { unitId: "b324", index: 1, slot: "weapon", gear: "sword", holdId: "h324", hereId: "mill324" });
  const swords = AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "weapon", gear: "sword", holdId: "h324", hereId: "mill324" });
  const nine = AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "shield", gear: "shield", n: 9, holdId: "h324", hereId: "mill324" });
  const canNine = ML.bandCan(who.bands[0]);
  const ten = AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "shield", gear: "shield", n: 10, holdId: "h324", hereId: "mill324" });
  const canTen = ML.bandCan(who.bands[0]);
  const gapsAfter = ML.bandGaps(who.bands[0], {}).map(g => g.missing);
  const after = ML.bandStrength(ML.resolvedUnit(who.bands, who.bands[0]), {}).effective;
  check("§324: ⛔ OUTFIT UP TO THE STOCK — where you stand, never a named person; 20 hands and 10 swords: 10 handed out, 10 short; shields returned and re-issued count toward the stock",
    !away.ok && !named.ok && /carries their own kit/.test(named.why) && swords.ok && swords.given === 10 && swords.short === 10
    && nine.ok && ten.ok && ten.given === 10 && AR.gearCount(h, "sword") === 0 && AR.gearCount(h, "shield") === 2 && !h.armory.sword,
    JSON.stringify({ away, named, swords, nine, ten, armory: h.armory }));
  check("§324: ⛔ SHIELDS ON HALF OF THEM PROTECT — read by `bandCan` itself, so a LONE band's losses hear it (bloodBand reads the raw unit): 9 of 20 is not half, 10 is; the 1.4× unwarded gap lifts",
    !canNine.includes("PROTECT") && canTen.includes("PROTECT") && gapsBefore.includes("PROTECT") && !gapsAfter.includes("PROTECT"),
    JSON.stringify({ canNine, canTen, gapsBefore, gapsAfter }));
  const stored = who.bands[0].contingents[0].quality;
  const again = ML.bandStrength(ML.resolvedUnit(who.bands, who.bands[0]), {}).effective;
  check("§324: ⛔ WHAT THEY CARRY LIFTS THEIR QUALITY in the resolved unit (half of them a sword's 0.1, half a shield's 0.05 → +0.075 each, 20 heads → +1.5) and never in the stored contingent, so a lift cannot compound",
    before === 22 && after === Math.round(22 + 20 * 0.075) && stored === 1 && again === after, JSON.stringify({ before, after, stored, again }));
  const bled = ML.bloodUnit(who.bands, "b324", 0.2, { cfg: {} });
  const kept = bled.bands[0].contingents[0].kit;
  const axes = (() => { h.armory = { ...h.armory, axe: 20 }; return AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "weapon", gear: "axe", holdId: "h324", hereId: "mill324" }); })();
  const back = AR.outfitContingent(who, { unitId: "b324", index: 0, slot: "shield", gear: null, holdId: "h324", hereId: "mill324" });
  check("§324: ⛑ THE KIT SURVIVES A CLASH (the normaliser carries it through); a different weapon sends the swords back to the armory; taking shields back returns them and the slot empties",
    kept?.weapon?.gear === "sword" && axes.ok && axes.returned?.gear === "sword" && AR.gearCount(h, "sword") === 10
    && back.ok && back.returned.n === 10 && AR.gearCount(h, "shield") === 12 && !who.bands[0].contingents[0].kit.shield,
    JSON.stringify({ kept, axes, back, armory: h.armory }));

  const eco = CT324.rules.economy;
  const rid = "the_gearlands";
  const each = AR.gearPrice("sword", rid, { economy: eco });
  const purseBefore = JSON.stringify(who.purse || null);
  const awaySell = AR.sellGear(who, "h324", { sword: 4 }, { hereId: "elsewhere", regionId: rid, economy: eco });
  const sold = AR.sellGear(who, "h324", { sword: 4, shield: 0 }, { hereId: "mill324", regionId: rid, economy: eco });
  check("§324: ⛔ GEAR SELLS AS ARMS, where the armory stands, at the place's price for arms, paid in its money",
    !awaySell.ok && JSON.stringify(who.purse || null) !== purseBefore && sold.ok && sold.sold.length === 1 && sold.value === 4 * each && each > 0
    && AR.gearCount(h, "sword") === 6 && typeof sold.said === "string" && sold.said.length > 0, JSON.stringify({ each, sold, purse: who.purse }));

  who.holdings[0].forgeOrder = { gear: "plate", left: 3 };
  const gm = H324.holdingsForGM(who, null, { hereId: "mill324", sayArmory: (x) => AR.armorySaid(x, AR.armoryTable()) }) || "";
  const roster = (FL.rosterForGM(who, { content: CT324 }) || []).join("\n");
  const W324 = rd("engine/worldtick.js").replace(/\r\n/g, "\n");
  const G324 = rd("engine/gm_registry.js").replace(/\r\n/g, "\n");
  check("§324: ⛔ THE GM IS TOLD — the hold's line says its armory and its forge's order (injected by the registry), the roster says what each unit carries; and the world tick works the forge each pass",
    /its armory holds [^;]*\b6 swords\b/.test(gm) && /its armory holds [^;]*\b12 shields\b/.test(gm) && !/\baxes\b/.test(gm)   /* the twenty axes were handed out */
    && /; its forge is making suits of plate, 3 to go/.test(gm) && /carrying 20 axes/.test(roster)
    && /const made = tickArmory\(h, \{ cfg: holdCfg, armory: content\?\.rules\?\.economy\?\.armory \|\| null \}\);\n\s*if \(made\?\.said\) news\.push\(made\.said\);/.test(W324)
    && /sayArmory: \(h\) => armorySaid\(h, armoryTable\(env\.CONTENT\?\.rules\?\.economy\?\.armory \|\| null\)\)/.test(G324),
    JSON.stringify({ gm: gm.slice(-160), roster: roster.slice(0, 200) }));
  const A324 = rd("app.js").replace(/\r\n/g, "\n").split("\n").filter(l => !/^\s*\/\//.test(l)).join("\n");
  check("§324: ⛑ WHERE THE PLAYER DOES IT — the hold card's order and Sell gear, the Bands tab's Outfit, each bound to its handler",
    /\[data-make-order\]"\)\) btn\.onclick/.test(A324) && /\[data-make-stop\]/.test(A324) && /\[data-sell-gear\]"\)\) btn\.onclick = \(\) => showSellGear\(/.test(A324)
    && /\[data-cg-outfit\]"\)\) b\.onclick = \(\) => showOutfit\(/.test(A324) && /const r = outfitContingent\(character, \{ unitId, index, slot,/.test(A324)
    && /const r = sellGear\(character, h\.id, counts\(\),/.test(A324));
}

// ══════════ §325 · CCODE-446 — THE EARLY RETURN SAID NOTHING ══════════
// Found verifying the armory: the forge made six swords on a real pass and no line said so. `runWorldTick` returns early when the character's
// day has not moved — the state live saves sit in — and on that path it only RETURNED its news, which its one caller ignores.
console.log("\n── §325 · a hold's pass is said on the early-return path too — the news reaches the log and the GM, not only a return nobody reads ──");
{
  const { runWorldTick: rwt325 } = await import("../engine/worldtick.js");
  const { worldCount: wc325 } = await import("../engine/worldtime.js");
  const { loadContentHeadless: lch325 } = await import("./headless_content.mjs");
  const C325 = await lch325();
  const mk = () => ({ id: "c325", name: "Tester", clock: { day: 14 }, npcRegistry: {}, purse: { crystal: 50, coin: 0, paper: 0, marks: 0, scrip: {} },
    worldState: { lastTickDay: 14, eventStages: {}, spectrumDrift: {}, news: [], unseenNews: [] },
    holdings: [{ id: "h325", name: "Fell Pell", kind: "post", locationId: "millbrook", condition: "steady", steward: null,
      lastMovedWorldCount: wc325() - 500, store: { raw_material: 9 }, features: [{ kind: "forge" }], forgeOrder: { gear: "sword", left: 3 } }] });
  const c = mk();
  const r = await rwt325({ character: c, content: C325, currentDay: 14, advanceAssignments: async () => ({ advancements: [] }) });
  const said = (arr) => (arr || []).map(n => n?.text || "").filter(t => /Fell Pell made 3 swords — the order is filled\./.test(t));
  check("§325: ⛔ ON THE EARLY RETURN (the character's day parked, world time moved) the hold's pass is WRITTEN — the forge's line reaches the news the flash and the log read, and the GM's buffer — not only the return value nobody reads",
    r.ticked === true && c.holdings[0].armory?.sword === 3 && said(c.worldState.unseenNews).length === 1 && said(c.worldState.news).length === 1
    && said(r.news).length === 1, JSON.stringify({ ticked: r.ticked, unseen: (c.worldState.unseenNews || []).map(n => n.text), armory: c.holdings[0].armory }));
  const quiet = mk(); quiet.holdings = [];
  const before = JSON.stringify(quiet.worldState);
  await rwt325({ character: quiet, content: C325, currentDay: 14, advanceAssignments: async () => ({ advancements: [] }) });
  check("§325: ⛑ …and a pass with nothing to say writes nothing", JSON.stringify(quiet.worldState.news) === JSON.stringify(JSON.parse(before).news)
    && (quiet.worldState.unseenNews || []).length === 0);
  const { storeNews: sn325 } = await import("../engine/holdings.js");
  const kept = sn325({ name: "Fell Pell" }, { keeperSold: { by: "pell", goods: { raw_material: 5, mech_parts: 8 }, crystal: 52, said: "52 crystal" } });
  check("§325: ⛔ …and the keeper's sale has a line — `keeperSold` was written every pass and read by nothing, so a hold's main income reached the purse unsaid while three crystal of alms were told",
    kept.includes("Fell Pell's keeper sold 5 raw material, 8 mech parts for 52 crystal."), JSON.stringify(kept));
}

// ══════════ §326 · CCODE-447 — THE PICTURE SERVICE'S REFUSAL, SAID ══════════
// Erik, with a screenshot: "The image generation seems to be having issues" — the viewer said "this one didn't come through — try Draw
// again". Measured: Pollinations answers every new picture, on every model, with 500 and "Insufficient balance … pollen". No retry helps.
console.log("\n── §326 · a refusing picture service is named, not retried into — and a refusal deletes nothing ──");
{
  const ART326 = await import("../engine/art.js");
  const body = `{"error":"Internal Server Error","message":"Gen Sana request failed with 402: {\"success\":false,\"error\":{\"message\":\"Insufficient balance. This request costs ~0.0001 pollen, but your available balance is 0.0000. Top up at https://enter.pollinations.ai/top-up.\",\"code\":\"INSUFFICIENT_BALANCE\"},\"status\":402}"}`;
  check("§326: ⛔ THE REFUSAL IS READ — the service's real 500 body is 'unpaid'; any other failure, and any success, is not",
    ART326.serviceRefusal(500, body) === "unpaid" && ART326.serviceRefusal(402, "Insufficient balance") === "unpaid"
    && ART326.serviceRefusal(500, '{"error":"Internal Server Error"}') === null && ART326.serviceRefusal(200, body) === null && ART326.serviceRefusal(503, "") === null);
  check("§326: ⛑ …and what the player is told says what happened and that what they have is safe — never 'try again'",
    // ⛔ CCODE-455: one constant became four reasons (`refusedSaid`), because "a service still being set up" is not "a service that tried
    // and failed" — and the player is owed the difference. The property is the same for every one of them.
    ["unpaid", "unbuilt", "undrawn", "unasked"].every(w => /the pictures you already have still show/.test(ART326.refusedSaid(w)) && !/try/i.test(ART326.refusedSaid(w)))
    && /charges for new pictures/.test(ART326.refusedSaid("unpaid")) && new Set(["unpaid", "unbuilt", "undrawn", "unasked"].map(w => ART326.refusedSaid(w))).size === 4);
  const A326 = rd("app.js").replace(/\r\n/g, "\n").split("\n").filter(l => !/^\s*\/\//.test(l)).join("\n");
  check("§326: ⛔ A REFUSAL DELETES NOTHING — the probe reads the body on a failed response and STILL answers 'unknown', which `mintAction` leaves alone; the viewer and the gallery's retry ask before promising",
    /if \(!res\.ok\) \{[\s\S]{0,300}const refused = serviceRefusal\(res\.status, body\);\n\s*if \(refused\) _artRefusal = \{ why: refused, at: Date\.now\(\) \};\n\s*return \{ verdict: "unknown",/.test(A326)
    && /shownImg\.onerror = async \(\) => \{[\s\S]{0,200}const refused = await artRefusalOf\(it\.url\);/.test(A326)
    && /\[data-galretry\]"\)\) b\.onclick = async \(\) => \{[\s\S]{0,250}const refusal = await artRefusalOf\(/.test(A326)
    && ART326.mintAction("unknown", 0, 2) === "leave");
}

// ══════════ §327 · CCODE-448 — THE ORDER OF BATTLE: A TURN BY STANCE ══════════
// Erik, of the Fell Pell prototype: "I don't see the party or the legion tabs nor the other updates from the prototype yet. I would
// prioritize those." One model (engine/orderofbattle.js), rolled with the Jobs tab's dice, read by the Party tab, a band's turn and the Legion.
console.log("\n── §327 · the order of battle — stances cut a turn into slots, each person takes what they are best at next to the rest, and the party's round is told ──");
{
  const OB = await import("../engine/orderofbattle.js");
  const { buildFunctionIndex: bfi327 } = await import("../engine/functions.js");
  const { loadContentHeadless: lch327 } = await import("./headless_content.mjs");
  const C327 = await lch327();
  const fnIndex = bfi327(C327.functionVocabulary);
  const rules = C327.rules;
  const T = OB.stanceTable();
  check("§327: ⚑ THREE STANCES, the prototype's weights Erik reviewed; an authored rules.stances wins weight by weight; anything unknown is balanced",
    OB.STANCE_NAMES.join() === "cautious,balanced,aggressive" && T.aggressive.w.HARM === 4 && T.cautious.w.KNOW === 3 && T.balanced.w.RESTORE === 1.5
    && OB.stanceTable({ aggressive: { w: { HARM: 6 } } }).aggressive.w.HARM === 6 && OB.stanceTable({ aggressive: { w: { HARM: 6 } } }).aggressive.w.SHAPE === 2
    && OB.stanceOf("reckless") === "balanced" && /prototype/.test(OB.STANCE_DEFAULTS._standIn));
  const six = OB.slotsFor(6, T.cautious.w);
  check("§327: ⛔ THE STANCE CUTS THE TURN INTO SLOTS — six people cautious read 2 · guard 2 · mend 1 · strike 1; the slots always sum to the heads",
    six.KNOW === 2 && six.PROTECT === 2 && six.RESTORE === 1 && six.HARM === 1 && Object.values(six).reduce((a, b) => a + b, 0) === 6
    && Object.values(OB.slotsFor(0, T.balanced.w)).every(v => v === 0) && Object.values(OB.slotsFor(13, T.aggressive.w)).reduce((a, b) => a + b, 0) === 13, JSON.stringify(six));
  const pick = OB.hungarian([[4, 1, 3], [2, 0, 5], [3, 2, 2]]);
  check("§327: ⛑ …and the assignment is the optimum, not a greedy pass (the classic 3×3: total 5)", pick.join() === "1,0,2", JSON.stringify(pick));
  const sheet = { attributes: { physical: 6, mental: 6, social: 6, practical: 6 }, subAttributes: {} };
  const striker = { id: "a", short: "Striker", level: 20, sheet, skills: [{ id: "blade", name: "Blade", function: "strike", attribute: "physical", rank: 3, tier: 1 }, { id: "wall", name: "Wall", function: "shield", attribute: "physical", rank: 1, tier: 1 }] };
  const guard = { id: "b", short: "Guard", level: 20, sheet, skills: [{ id: "jab", name: "Jab", function: "strike", attribute: "physical", rank: 1, tier: 1 }, { id: "bulwark", name: "Bulwark", function: "shield", attribute: "physical", rank: 3, tier: 1 }] };
  const hands = { id: "unit:b1:0", isUnit: true, n: 12, quality: 1, does: ["HARM", "PROTECT"], sheet, short: "12 spears", label: "spears" };
  const t = OB.allocateTurn([striker, guard, hands], { stance: "balanced", rules, fnIndex, opposed: 5 });
  const ta = OB.allocateTurn([hands], { stance: "aggressive", rules, fnIndex, opposed: 5 });
  const harmHands = (ta.rows.HARM || []).find(r => r.unit)?.n, protHands = (ta.rows.PROTECT || []).find(r => r.unit)?.n;
  check("§327: ⛔ EACH TAKES WHAT THEY ARE BEST AT NEXT TO THE REST — the striker strikes and the guard guards (not both the striker's best); twelve hands aggressive split 10 strike · 2 guard, each with the hands' own dice",
    t.of.a === "HARM" && t.of.b === "PROTECT" && (t.rows.HARM || []).some(r => r.id === "a" && r.craft === "Blade") && (t.rows.PROTECT || []).some(r => r.id === "b" && r.craft === "Bulwark")
    && harmHands === 10 && protHands === 2 && ta.expected.HARM > ta.expected.PROTECT && ta.expected.HARM > 0, JSON.stringify({ of: t.of, harmHands, protHands, exp: ta.expected }));
  const seer = { id: "s", short: "Seer", level: 20, sheet, skills: [{ id: "sight", name: "Far Sight", function: "reveal", attribute: "mental", rank: 3, tier: 1 }, { id: "cut", name: "Cut", function: "strike", attribute: "physical", rank: 2, tier: 1 }] };
  const cautious = OB.allyChoice(seer, { stance: "cautious", rules, fnIndex, opposed: 5 });
  const aggressive = OB.allyChoice(seer, { stance: "aggressive", rules, fnIndex, opposed: 5 });
  const preferred = OB.allyChoice(seer, { stance: "balanced", prefer: ["cut"], rules, fnIndex, opposed: 5 });
  check("§327: ⛔ AN ALLY'S CRAFT FOLLOWS THEIR STANCE — cautious, the seer reads; aggressive, they cut; and a preferred craft (★) weighs half again",
    cautious?.family === "KNOW" && aggressive?.name === "Cut" && preferred?.name === "Cut" && preferred.preferred === true,
    JSON.stringify({ cautious: cautious?.name, aggressive: aggressive?.name, preferred: preferred?.name }));
  let k = 0; const rng = () => [0.01, 0.99, 0.3][k++ % 3];
  const round = OB.partyRound([striker, guard, seer], { orders: { s: { stance: "cautious" } }, forward: ["a"], rules, fnIndex, opposed: 5, rng });
  check("§327: ⛔ THE PARTY'S ROUND — the ones brought forward are told first, by name and craft; the rest act for themselves in the line; the outcomes are decided and the GM tells them",
    round.forward.length === 1 && round.forward[0].name === "Striker" && round.folded.length === 2
    && /^THE PARTY'S ROUND/.test(round.directive) && /- Striker uses Blade \(strike\) — STRONG SUCCESS\. Say what it does, by name\./.test(round.directive)
    && /In the line, acting for themselves: Guard uses/.test(round.directive) && /The outcomes are decided; tell them, do not change them\./.test(round.directive), round.directive);
  const A327 = rd("app.js").replace(/\r\n/g, "\n").split("\n").filter(l => !/^\s*\/\//.test(l)).join("\n");
  const E327 = rd("engine/encounters.js").replace(/\r\n/g, "\n");
  const { rosterForGM: rgm327 } = await import("../engine/fellowship.js");
  const who = { level: 20, bands: [{ id: "b1", name: "Ridge Watch", stance: "aggressive", condition: "fresh", contingents: [{ n: 12, quality: 1, does: ["HARM", "MARTIAL"] }] }], npcRegistry: {} };
  const roster = (rgm327(who, { content: C327 }) || []).join("\n");
  check("§327: ⛔ WHERE IT REACHES PLAY — the Party and Legion tabs are on the bar and wired; the Party tab's pick is the fight's default in the engine AND the panel; every fight turn hands the GM the party's round; the GM's roster says a band's stance",
    /id="tab-party">⚑ Party</.test(A327) && /id="tab-legion">♜ Legion</.test(A327) && /go\("tab-party", \(\) => renderPartyTab\(\)\)/.test(A327) && /go\("tab-legion", \(\) => renderLegionTab\(\)\)/.test(A327)
    && /chosen: state\.broughtForward \|\| character\?\.partyForward \|\| null/.test(E327) && /chosen: st\.broughtForward \|\| character\.partyForward \|\| null/.test(A327)
    && /if \(partyLine\) beats\.push\(partyLine\);/.test(A327) && /partyRound\(allies, \{ orders: character\.allyOrders \|\| \{\}, forward: fwdIds/.test(A327)
    && /its stance: aggressive — it strikes and breaks first/.test(roster) && /\$\{u\.isLegion \? "" : bandTurnHtml\(u\)\}/.test(A327), roster.slice(0, 200));
}

// ══════════ §328 · CCODE-449 — ONE PERSON, ONE SEAT; AND THE COUNT IS THE ALLIES ══════════
// Found building the Party tab on Silas's save: Marrow sat twice (a companion AND on the company roster, one id), and the fight engine counted
// the player into "allies present" — a party of three read as four and one was folded, against Erik's 2026-09-12 ruling.
console.log("\n── §328 · a companion on the company roster is one person in a fight, and three allies all act — in the engine as on the panel ──");
{
  const CB328 = await import("../engine/combatants.js");
  const ML328 = await import("../engine/melee.js");
  const who = { id: "c328", name: "Tester", level: 20, companions: ["marrow"], company: [{ npcId: "marrow", roles: ["ally"] }, { npcId: "pell", roles: ["ally"] }, { npcId: "veth", roles: [] }] };
  const seat = CB328.alliesOf(who, { companions: { marrow: { id: "marrow", name: "Marrow", assistTags: ["reveal"] } }, npcs: { pell: { name: "Pell" }, veth: { name: "Veth" } }, company: who.company });
  const ids = seat.filter(a => !a.isPlayer).map(a => a.id);
  const marrow = seat.find(a => a.id === "marrow");
  check("§328: ⛔ ONE PERSON, ONE SEAT — a companion who is also on the company roster is seated once, carrying the roster's roles",
    ids.length === 3 && ids.filter(x => x === "marrow").length === 1 && marrow.kind === "companion" && (marrow.roles || []).includes("ally"), JSON.stringify(ids));
  const E328 = rd("engine/encounters.js").replace(/\r\n/g, "\n");
  const present = seat.filter(a => a.present);   // what the engine's `partyPresent` holds — the player included
  const engineCount = present.filter(a => a && !a.isPlayer && a.kind !== "player").length;
  const lead = { slots: 3, why: "you lead 3" };
  const engineSplit = ML328.lineSplit(seat, { chosen: null, lead, presentCount: engineCount });
  const panelSplit = ML328.lineSplit(seat, { chosen: null, lead, presentCount: seat.filter(a => a.present !== false && !a.isPlayer && a.kind !== "player").length });
  check("§328: ⛔ THE COUNT IS THE ALLIES — the engine passes allies present without the player, so three allies all act (Erik: \"3 or fewer … everyone acts and no one is folded\"), exactly as the panel says",
    /presentCount: partyPresent\.filter\(a => a && !a\.isPlayer && a\.kind !== "player"\)\.length/.test(E328) && !/presentCount: partyPresent\.length/.test(E328)
    && engineCount === 3 && engineSplit.everyoneActs && engineSplit.folded.length === 0 && panelSplit.everyoneActs
    && ML328.lineSplit(seat, { chosen: null, lead, presentCount: present.length }).folded.length === 1,
    JSON.stringify({ engineCount, engine: engineSplit.why, withPlayerCounted: ML328.lineSplit(seat, { chosen: null, lead, presentCount: present.length }).why }));
}

// ══════════ §329 · CCODE-451 — A COMPANION WHO IS ALSO A PERSON IS AT LEAST THEMSELVES ══════════
// Erik: "silas' save has Maren at lvl 33 but she's actually in the mid 60s". The companion branch returned the character's level (a floor)
// before asking who she is — a legendary warden whose own derived level on world day 81 is 63.
console.log("\n── §329 · a companion's level is the higher of the character's floor and who they are ──");
{
  const FL329 = await import("../engine/fellowship.js");
  const { loadContentHeadless: lch329 } = await import("./headless_content.mjs");
  const C329 = await lch329();
  const who = { level: 33, companions: ["marrow", "aevi"], npcRegistry: { marrow: { name: "Maren (Marrow) Ossitide", aliases: ["Huginn", "Marrow", "Maren Ossitide"] } } };
  const maren = FL329.levelOfPerson(who, "marrow", { content: C329, worldDay: 81 });
  const aevi = FL329.levelOfPerson(who, "aevi", { content: C329, worldDay: 81 });
  const young = FL329.levelOfPerson({ ...who, level: 70 }, "marrow", { content: C329, worldDay: 81 });
  const F329 = rd("engine/fellowship.js").replace(/\r\n/g, "\n");
  check("§329: ⛔ MAREN IS HERSELF — her record resolves to the legendary warden, and she stands at her own derived level (63 on world day 81), not Silas's 33; a companion who is nobody's record keeps the character's level as the floor; and the floor still lifts her beside a level-70 character",
    maren >= 60 && maren < 70 && aevi === 33 && young === 70
    && /return Math\.max\(entry \? derivedOf\(entry\) : 0, num\(character\?\.level, 0\) \|\| 0\);/.test(F329), JSON.stringify({ maren, aevi, young }));
}

// ══════════ §330 · CCODE-450 — STANDING WORK AT A HOLD ══════════
// The Fell Pell prototype's Holds tab: people with no job put to what a hold needs; each good day banks toward what lasts, or the work changes
